
/* Labor-Werkstatt (wird von quellen/labor_einbetten.py eingesetzt) */
const LABOR_QUELLE = "<!doctype html>\n<html lang=\"de\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Labor & Werkstatt · Testversion<\/title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\"><link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@400;500;600&family=IBM+Plex+Sans:wght@400;500;600;700&family=IBM+Plex+Serif:wght@500;600&display=swap\" rel=\"stylesheet\">\n<style>\n:root{\n  --papier:#F1F3EF; --karte:#FFFFFF; --tinte:#16212B; --tinte2:#48565F; --stumm:#7A8891;\n  --linie:#DCE1D8; --linie2:#EEF0EA;\n  --rot:#AE3A2C; --rot-bg:#FAEDEA; --moos:#2C6A4E; --moos-bg:#E6F1EA; --blau:#2A4D7A; --blau-bg:#E8EEF6; --gold:#9A6B12; --gold-bg:#FBF3E2;\n  --r:8px; --schrift:'IBM Plex Sans',system-ui,sans-serif; --serif:'IBM Plex Serif',Georgia,serif; --mono:'IBM Plex Mono',ui-monospace,monospace;\n}\n*{box-sizing:border-box}\nbody{margin:0; background:var(--papier); color:var(--tinte); font-family:var(--schrift); line-height:1.5}\nh1,h2,h3{font-family:var(--serif); font-weight:600; margin:0; letter-spacing:-.01em}\nbutton{font-family:inherit; cursor:pointer}\ninput,select{font-family:inherit; font-size:inherit; color:inherit}\n.kopf{display:flex; align-items:center; gap:1rem; padding:.8rem 1.2rem; background:var(--karte); border-bottom:1px solid var(--linie); position:sticky; top:0; z-index:5}\n.kopf h1{font-size:1.15rem}\n.stempel{font-family:var(--mono); font-size:.66rem; font-weight:700; letter-spacing:.14em; text-transform:uppercase; color:var(--gold); border:1.5px solid var(--gold); border-radius:4px; padding:2px 6px}\n.zur-uebersicht{font-size:.8rem; color:var(--stumm); text-decoration:none; border:1px solid var(--linie); border-radius:999px; padding:.2rem .6rem}\n.rahmen{display:grid; grid-template-columns:270px 1fr; gap:1.2rem; max-width:1300px; margin:0 auto; padding:1.2rem}\n@media (max-width:900px){ .rahmen{grid-template-columns:1fr} .navi{position:static!important; max-height:none!important} }\n.navi{position:sticky; top:4.2rem; align-self:start; max-height:calc(100vh - 5rem); overflow:auto; background:var(--karte); border:1px solid var(--linie); border-radius:var(--r); padding:.6rem}\n.navi h3{font-family:var(--mono); font-size:.66rem; letter-spacing:.16em; text-transform:uppercase; color:var(--stumm); margin:.7rem .4rem .3rem}\n.navi a{display:flex; justify-content:space-between; gap:.5rem; padding:.35rem .55rem; border-radius:6px; color:var(--tinte); text-decoration:none; font-size:.9rem}\n.navi a:hover{background:var(--linie2)}\n.navi a.aktiv{background:var(--tinte); color:#fff}\n.navi a .fort{font-family:var(--mono); font-size:.7rem; opacity:.75}\n.karte{background:var(--karte); border:1px solid var(--linie); border-radius:var(--r); padding:1.1rem 1.3rem; margin-bottom:1rem}\n.augenbraue{font-family:var(--mono); font-size:.66rem; letter-spacing:.16em; text-transform:uppercase; color:var(--stumm); margin-bottom:.4rem}\n.lab-titel{font-size:1.35rem; margin-bottom:.3rem}\n.lab-intro{color:var(--tinte2); margin:.2rem 0 .2rem}\n.lab-grid{display:grid; grid-template-columns:minmax(0,1.5fr) minmax(260px,1fr); gap:1.1rem; align-items:start}\n@media (max-width:1100px){ .lab-grid{grid-template-columns:1fr} }\n.regler{display:grid; grid-template-columns:1fr auto; gap:.1rem .6rem; margin:.45rem 0}\n.regler label{font-size:.88rem; color:var(--tinte2)}\n.regler output{font-family:var(--mono); font-size:.88rem; font-weight:600; text-align:right; min-width:4.5em}\n.regler input[type=range]{grid-column:1 / -1; width:100%; accent-color:var(--blau)}\n.feld{display:flex; align-items:center; gap:.4rem; margin:.3rem 0; font-size:.9rem}\n.feld input[type=number]{width:6.5em; padding:3px 6px; border:1px solid var(--linie); border-radius:6px}\n.knopf{padding:.42rem .85rem; border-radius:6px; border:1px solid var(--linie); background:var(--karte); color:var(--tinte); font-size:.88rem}\n.knopf:hover{border-color:var(--tinte2)}\n.knopf.primaer{background:var(--tinte); color:#fff; border-color:var(--tinte)}\n.knopf:disabled{opacity:.45; cursor:default}\n.knoepfe{display:flex; flex-wrap:wrap; gap:.4rem; margin:.5rem 0}\n.term{font-family:var(--serif); font-size:1.15rem; margin:.3rem 0 .5rem; padding:.4rem .7rem; background:var(--linie2); border-radius:6px; display:inline-block}\n.info{font-size:.9rem; padding:.5rem .7rem; border-radius:6px; background:var(--blau-bg); color:var(--blau); margin:.5rem 0}\n.info.gut{background:var(--moos-bg); color:var(--moos)}\n.info.schlecht{background:var(--rot-bg); color:var(--rot)}\n.auftraege{list-style:none; padding:0; margin:.3rem 0 0}\n.auftraege li{display:flex; gap:.55rem; align-items:flex-start; padding:.4rem 0; border-bottom:1px solid var(--linie2); font-size:.92rem}\n.auftraege li .haken{flex:0 0 1.3rem; height:1.3rem; border:1.5px solid var(--linie); border-radius:50%; display:flex; align-items:center; justify-content:center; font-size:.8rem; color:#fff}\n.auftraege li.erledigt .haken{background:var(--moos); border-color:var(--moos)}\n.auftraege li.erledigt{color:var(--moos)}\n.fertig{margin-top:.6rem; font-weight:600; color:var(--moos); display:none}\n.fertig.an{display:block}\nsvg.plot{width:100%; height:auto; display:block; font-family:var(--schrift)}\ntable.lab{border-collapse:collapse; font-size:.88rem; font-variant-numeric:tabular-nums; width:100%}\ntable.lab th, table.lab td{border:1px solid var(--linie); padding:3px 7px; text-align:right}\ntable.lab th{background:var(--linie2); font-weight:600; text-align:center}\ntable.lab td:first-child, table.lab th:first-child{text-align:left}\ntable.lab tr.neu td{background:var(--gold-bg); transition:background 1s}\ntable.lab tr.summe td{font-weight:700; border-top:2px solid var(--tinte2)}\n.scroll{overflow-x:auto}\n.tkonten{display:grid; grid-template-columns:repeat(auto-fill,minmax(260px,1fr)); gap:.7rem}\n.tk{border:1px solid var(--linie); border-radius:6px; padding:.3rem .5rem; font-size:.82rem; background:var(--karte)}\n.tk h4{margin:0 0 .2rem; font-size:.82rem; text-align:center; border-bottom:2px solid var(--tinte); padding-bottom:.15rem}\n.tk .seiten{display:grid; grid-template-columns:minmax(0,1fr) minmax(0,1fr)}\n.tk .seiten > div{padding:0 .3rem; min-height:2.2rem}\n.tk .seiten > div:first-child{border-right:2px solid var(--tinte)}\n.tk .z{display:flex; justify-content:space-between; gap:.3rem; font-variant-numeric:tabular-nums}\n.tk .z.neu{background:var(--gold-bg)}\n.tk .z.saldo{color:var(--blau); font-weight:600}\n.tk .z.summe{border-top:1px solid var(--tinte2); font-weight:700}\n.tk.zu{opacity:.75}\n.tk .knopf{padding:.15rem .45rem; font-size:.75rem; margin-top:.25rem; width:100%}\n.np-k{border:1.5px solid var(--tinte); border-radius:4px; font-size:.78rem; background:var(--karte); font-variant-numeric:tabular-nums}\n.np-k.krit{border-color:var(--rot); box-shadow:0 0 0 2px var(--rot-bg)}\n.np-k .r{display:grid; grid-template-columns:repeat(3,1fr); text-align:center}\n.np-k .r > div{border-right:1px solid var(--linie); padding:1px 2px; min-height:1.3em}\n.np-k .r > div:last-child{border-right:0}\n.np-k .r + .r{border-top:1px solid var(--linie)}\n.np-k .name{grid-column:2 / 4; text-align:left; font-weight:600}\n.np-k .wert{color:var(--blau); font-weight:600}\n.np-k .wert.neu{background:var(--gold-bg)}\n.legende{font-size:.78rem; color:var(--stumm)}\n.tk .z span:first-child{white-space:nowrap; overflow:hidden; text-overflow:ellipsis; min-width:0}\n.tk .z span:last-child{white-space:nowrap}\n.lab-grid > .karte{margin-bottom:0}\n.lab-grid{margin-bottom:1rem}\n.auftrag-kopf{display:flex; justify-content:space-between; align-items:center; gap:.5rem}\n.knopf.klein{padding:.15rem .5rem; font-size:.75rem}\n.auftraege li{cursor:default}\n.auftraege li:not(.erledigt){cursor:pointer}\n.auftraege li .haken{color:var(--stumm); font-family:var(--mono); font-size:.72rem}\n.auftraege li.erledigt .haken{color:#fff; font-size:.8rem}\n.auftraege li.aktuell{background:var(--gold-bg); border-radius:6px; padding-left:.35rem; padding-right:.35rem; font-weight:500}\n.auftraege li.aktuell .haken{border-color:var(--gold); color:var(--gold); font-weight:700}\n.weiter-meldung{display:none; margin-top:.6rem; padding:.55rem .7rem; border-radius:6px; background:var(--moos-bg); color:var(--moos); font-weight:600}\n.weiter-meldung.an{display:flex; flex-wrap:wrap; align-items:center; gap:.5rem}\n.weiter-meldung span{flex:1 1 100%}\n.info:empty{display:none}\n.knopf.getan{background:var(--moos-bg); color:var(--moos); border-color:var(--moos-bg); opacity:1}\n.umlage-grid{display:grid; grid-template-columns:repeat(5,minmax(0,1fr)); gap:.4rem; margin:.3rem 0}\n.umlage-grid label{display:flex; flex-direction:column; gap:.15rem; font-size:.75rem; color:var(--tinte2)}\n.umlage-grid input{width:100%; padding:3px 6px; border:1px solid var(--linie); border-radius:6px; text-align:center}\n.umlage-grid input:disabled{background:var(--linie2)}\n.np-k.dran{border-color:var(--gold); box-shadow:0 0 0 3px var(--gold-bg)}\n.np-k input.np-ein{width:100%; box-sizing:border-box; border:1px solid var(--gold); border-radius:3px; padding:0 2px; font:inherit; font-size:.78rem; text-align:center; background:#fff; color:var(--tinte); -moz-appearance:textfield}\n.np-k input.np-ein::-webkit-inner-spin-button{display:none}\n.np-k input.np-ein.falsch{border-color:var(--rot); background:var(--rot-bg)}\n.np-legende{display:flex; gap:1rem; align-items:center; flex-wrap:wrap; margin-bottom:.6rem}\n.np-legende .np-k .r > div{color:var(--stumm); font-size:.72rem}\n.np-legende .legende{flex:1 1 320px}\n.umlage-grid input.falsch{border-color:var(--rot); background:var(--rot-bg)}\n\n/* eingebettet in einen Trainer */\nbody.solo .kopf, body.solo .navi{display:none}\nbody.solo .rahmen{grid-template-columns:1fr; padding:.4rem 0; max-width:none}\nbody.solo{background:transparent}\n<\/style><\/head>\n<body>\n<header class=\"kopf\"><a class=\"zur-uebersicht\" href=\"../index.html\">← Startseite<\/a><h1>Labor &amp; Werkstatt<\/h1><span class=\"stempel\">Testversion<\/span><\/header>\n<div class=\"rahmen\"><nav class=\"navi\" id=\"navi\" aria-label=\"Labore\"><\/nav><main id=\"haupt\"><\/main><\/div>\n<script>\n/* ---------- Mathematik: Hilfsfunktionen (Zahlen, Terme, Schaubilder) ---------- */\n// Zahl im deutschen Format mit echtem Minuszeichen\nconst maZ = (v, d) => { const f = Math.pow(10, d == null ? 2 : d), r = Math.round(v * f) / f; return (r < 0 ? '−' : '') + Math.abs(r).toLocaleString('de-DE', {maximumFractionDigits:d == null ? 2 : d}); };\n// Integral mit Grenzen übereinander (obere Grenze oben, untere unten) und Auswertungsklammer [F(x)] mit Grenzen\nconst MA_GR = (u, o) => `<span class=\"ma-int-g\"><span class=\"ma-int-o\">${o}<\/span><span class=\"ma-int-u\">${u}<\/span><\/span>`;\nconst maI = (u, o) => `<span class=\"ma-int\"><span class=\"ma-int-z\">∫<\/span>${MA_GR(u, o)}<\/span>`;\nconst maKl = (inhalt, u, o) => `<span class=\"ma-int\"><span>[${inhalt}]<\/span>${MA_GR(u, o)}<\/span>`;\n(() => { if (typeof document === 'undefined' || document.getElementById('ma-int-css')) return;\n  const st = document.createElement('style'); st.id = 'ma-int-css';\n  st.textContent = '.ma-int{display:inline-flex;align-items:center;vertical-align:middle;white-space:nowrap;line-height:1;margin:.3em 0}'\n    + '.ma-int-z{font-size:1.75em;line-height:1;font-weight:300;margin-right:.02em}'\n    + '.ma-int-g{display:inline-flex;flex-direction:column;justify-content:space-between;font-size:.68em;line-height:1;margin:0 .2em 0 .05em;min-height:2.6em}'\n    + '.ma-int-o{transform:translateY(-.15em)}.ma-int-u{transform:translateY(.25em)}';\n  (document.head || document.documentElement).appendChild(st); })();\nconst maK = v => v < 0 ? '(' + maZ(v) + ')' : maZ(v);   // in Klammern, wenn negativ\nconst MA_HOCH = {2:'²', 3:'³', 4:'⁴', 5:'⁵'};\n// Polynom aus Koeffizienten (höchster Grad zuerst): maPoly([0.5, -2, 0, 1]) → 0,5x³ − 2x² + 1\nfunction maPoly(k, v){\n  v = v || 'x'; const n = k.length - 1; let s = '';\n  k.forEach((a, i) => { const g = n - i; if (!a) return;\n    const b = Math.abs(a), z = g === 0 ? maZ(b) : (b === 1 ? '' : maZ(b)) + v + (g > 1 ? MA_HOCH[g] || '<sup>' + g + '<\/sup>' : '');\n    s += s ? (a < 0 ? ' − ' : ' + ') + z : (a < 0 ? '−' : '') + z; });\n  return s || '0';\n}\nconst maLin = (m, n) => maPoly([m, n]);\n// Linearfaktor (x − r)\nconst maFakt = r => r === 0 ? 'x' : '(x ' + (r < 0 ? '+ ' + maZ(-r) : '− ' + maZ(r)) + ')';\n// a·e^(kx) + b als HTML\nfunction maExp(a, k, b, v){\n  v = v || 'x'; const ex = (k === 1 ? '' : k === -1 ? '−' : maZ(k)) + v;\n  return (a === 1 ? '' : a === -1 ? '−' : maZ(a) + '·') + 'e<sup>' + ex + '<\/sup>' + (b ? (b < 0 ? ' − ' : ' + ') + maZ(Math.abs(b)) : '');\n}\nconst maF = (name, term, v) => `<i>${name}<\/i>(${v || 'x'}) = ${term}`;\nconst maR = v => Math.round(v * 100) / 100;\n// sortierte Liste\nconst maSort = a => a.slice().sort((x, y) => x - y);\n\n/* Schaubild: maGraf([{f, name, farbe}], {x0, x1, y0, y1, xs, ys, punkte:[[x, y]]}) */\nfunction maGraf(kurven, o){\n  const Wd = 420, H = 320, l = 34, r = 14, t = 14, b = 28, pw = Wd - l - r, ph = H - t - b;\n  const X = x => l + (x - o.x0) / (o.x1 - o.x0) * pw, Y = y => t + ph - (y - o.y0) / (o.y1 - o.y0) * ph;\n  const xs = o.xs || 1, ys = o.ys || 1;\n  let g = '';\n  for (let x = Math.ceil(o.x0 / xs) * xs; x <= o.x1 + 1e-9; x += xs) g += `<line x1=\"${X(x)}\" x2=\"${X(x)}\" y1=\"${t}\" y2=\"${t + ph}\" stroke=\"currentColor\" stroke-opacity=\".13\"/>` + (Math.abs(x) > 1e-9 ? `<text x=\"${X(x)}\" y=\"${Math.min(Math.max(Y(0) + 14, t + 12), t + ph + 16)}\" font-size=\"10\" text-anchor=\"middle\" fill=\"currentColor\" fill-opacity=\".8\">${maZ(x)}<\/text>` : '');\n  for (let y = Math.ceil(o.y0 / ys) * ys; y <= o.y1 + 1e-9; y += ys) g += `<line x1=\"${l}\" x2=\"${l + pw}\" y1=\"${Y(y)}\" y2=\"${Y(y)}\" stroke=\"currentColor\" stroke-opacity=\".13\"/>` + (Math.abs(y) > 1e-9 ? `<text x=\"${Math.min(Math.max(X(0) - 5, l - 4), l + pw)}\" y=\"${Y(y) + 3.5}\" font-size=\"10\" text-anchor=\"end\" fill=\"currentColor\" fill-opacity=\".8\">${maZ(y)}<\/text>` : '');\n  const ax = (o.y0 <= 0 && o.y1 >= 0 ? `<line x1=\"${l}\" x2=\"${l + pw + 6}\" y1=\"${Y(0)}\" y2=\"${Y(0)}\" stroke=\"currentColor\" stroke-width=\"1.3\"/><text x=\"${l + pw + 4}\" y=\"${Y(0) - 6}\" font-size=\"12\" text-anchor=\"end\" fill=\"currentColor\" font-style=\"italic\">x<\/text>` : '')\n    + (o.x0 <= 0 && o.x1 >= 0 ? `<line x1=\"${X(0)}\" x2=\"${X(0)}\" y1=\"${t + ph}\" y2=\"${t - 6}\" stroke=\"currentColor\" stroke-width=\"1.3\"/><text x=\"${X(0) + 6}\" y=\"${t + 6}\" font-size=\"12\" fill=\"currentColor\" font-style=\"italic\">y<\/text>` : '');\n  const farben = ['var(--rot,#AE3A2C)', 'var(--moos,#2C6A4E)', 'var(--tinte2,#2A4D7A)'];\n  const kv = kurven.map((k, i) => { const pts = [], n = 240;\n    for (let j = 0; j <= n; j++){ const x = o.x0 + (o.x1 - o.x0) * j / n, y = k.f(x); if (Number.isFinite(y)) pts.push(X(x).toFixed(1) + ',' + Y(Math.max(Math.min(y, o.y1 + (o.y1 - o.y0)), o.y0 - (o.y1 - o.y0))).toFixed(1)); }\n    return `<polyline points=\"${pts.join(' ')}\" fill=\"none\" style=\"stroke:${k.farbe || farben[i]}\" stroke-width=\"2.4\"/>`; }).join('');\n  const pos = k => { if (k.lx != null) return [k.lx, k.ly]; for (let j = 100; j >= 0; j--){ const x = o.x0 + (o.x1 - o.x0) * j / 100, y = k.f(x); if (y > o.y0 + (o.y1 - o.y0) * 0.08 && y < o.y1 - (o.y1 - o.y0) * 0.08) return [x - (o.x1 - o.x0) * 0.04, y + (o.y1 - o.y0) * 0.04]; } return [o.x1, o.y1]; };\n  const lab = kurven.map((k, i) => k.name ? `<text x=\"${X(pos(k)[0])}\" y=\"${Y(pos(k)[1])}\" text-anchor=\"end\" font-size=\"13\" font-weight=\"700\" font-style=\"italic\" style=\"fill:${k.farbe || farben[i]}\">${k.name}<\/text>` : '').join('');\n  const pk = (o.punkte || []).map(p => `<circle cx=\"${X(p[0])}\" cy=\"${Y(p[1])}\" r=\"3.5\" fill=\"currentColor\"/>`).join('');\n  return `<figure class=\"bl-grafik ma-grafik\" style=\"margin:8px 0\"><svg viewBox=\"0 0 ${Wd} ${H}\" role=\"img\" aria-label=\"Schaubild\" style=\"width:100%;max-width:${Wd}px;height:auto;font-family:inherit\">${g}${ax}\n    <svg x=\"${l}\" y=\"${t}\" width=\"${pw}\" height=\"${ph}\" viewBox=\"${l} ${t} ${pw} ${ph}\" overflow=\"hidden\">${kv}<\/svg>${lab}${pk}<\/svg><\/figure>`;\n}\n\n/* Vorberechnete Lösungen (Exponentialfunktionen brauchen ln) */\nfunction maExpWerte(a, k, b){ return {a, k, b, Lsy:maR(a + b), Lasy:b, Lnst:-b / a > 0 ? maR(Math.log(-b / a) / k) : 0}; }\nfunction maWachstum(b0, k, t1, g){ return {b0, k, t1, g, Lbt:maR(b0 * Math.exp(k * t1)), Ltd:maR(Math.log(2) / k), Ltg:maR(Math.log(g / b0) / k), Lp:maR((Math.exp(k) - 1) * 100)}; }\n// passender y-Bereich für ein Schaubild\nfunction maBereich(f, x0, x1, k0, k1){   // y-Bereich aus den Werten zwischen k0 und k1 (Standard: ganzer x-Bereich)\n  if (k0 == null){ k0 = x0; k1 = x1; }\n  let lo = Infinity, hi = -Infinity;\n  for (let j = 0; j <= 200; j++){ const y = f(k0 + (k1 - k0) * j / 200); if (Number.isFinite(y)){ lo = Math.min(lo, y); hi = Math.max(hi, y); } }\n  const sp = Math.max(hi - lo, 2), ys = sp <= 12 ? 1 : sp <= 30 ? 2 : sp <= 70 ? 5 : 10;\n  return {x0, x1, y0:Math.floor(Math.min(lo, 0) / ys) * ys - ys, y1:Math.ceil(Math.max(hi, 0) / ys) * ys + ys, xs:1, ys};\n}\n\n/* Zahlensätze für Rechenaufgaben: reproduzierbare Zufallsauswahl (gleicher Startwert → gleiche Sätze bei jedem Build)\n   maSaetze(startwert, anzahl, R => wert | null)  – R.g(a, b) ganze Zahl, R.p(liste) Auswahl, R.r() Zahl in [0;1)\n   maMit(saetze) → {werte, sets} für blBau('rechnung', …) */\nfunction maRnd(seed){ let s = (seed * 2654435761) >>> 0 || 1; return () => (s = (Math.imul(s, 1664525) + 1013904223) >>> 0) / 4294967296; }\nfunction maSaetze(seed, n, fn){\n  const r = maRnd(seed), R = {r, g:(a, b) => a + Math.floor(r() * (b - a + 1)), p:l => l[Math.floor(r() * l.length)]};\n  const aus = [], da = new Set();\n  for (let i = 0; i < n * 80 && aus.length < n; i++){ const v = fn(R); if (!v) continue; const k = JSON.stringify(v); if (da.has(k)) continue; da.add(k); aus.push(v); }\n  return aus;\n}\nconst maMit = s => ({werte:s[0], sets:s.slice(1)});\nconst maVz = v => v < 0 ? '− ' + maZ(-v) : '+ ' + maZ(v);   // „+ 3“ bzw. „− 3“ für Terme\nconst maAus = (...ids) => ids.map(id => ({id, t:id, aus:true}));   // verdeckte Größen (stehen im Text, nicht in der Tabelle)\nconst maFaktor = a => a === 1 ? '' : a === -1 ? '−' : maZ(a);       // Vorfaktor: 1 → „“, −1 → „−“\n// Scheitelform a(x − d)² + e\nconst maScheitel = (a, d, e) => maFaktor(a) + (d === 0 ? 'x²' : '(x ' + maVz(-d) + ')²') + (e ? ' ' + maVz(e) : '');\nconst maLn = v => maR(Math.log(v));\n\n/* Trigonometrie: Vielfache von π als Text (π/6, 3π/4 …), sonst Dezimalzahl; Funktionsterme a·sin(kx) + b */\nfunction maPi(v){\n  for (let d = 1; d <= 12; d++){ const n = Math.round(v / Math.PI * d); if (Math.abs(n * Math.PI / d - v) < 1e-9){\n    if (n === 0) return '0'; const g = (a, b) => b ? g(b, a % b) : a, t = g(Math.abs(n), d), z = n / t, q = d / t;\n    return (z < 0 ? '−' : '') + (Math.abs(z) === 1 ? '' : Math.abs(z)) + 'π' + (q === 1 ? '' : '/' + q); } }\n  return maZ(v);\n}\nconst MA_EXAKT = [[0, '0'], [0.5, '1/2'], [Math.SQRT2 / 2, '½√2'], [Math.sqrt(3) / 2, '½√3'], [1, '1']];\nfunction maExakt(v){ const e = MA_EXAKT.find(p => Math.abs(Math.abs(v) - p[0]) < 1e-9); return e ? (v < -1e-12 ? '−' : '') + e[1] : maZ(v); }\n// Argument kx als Text: kx ist z. B. 'x', '2x', '0,5x', 'π/2 · x'\nfunction maTrig(a, fn, kx, b){ return maFaktor(a) + fn + '(' + kx + ')' + (b ? ' ' + maVz(b) : ''); }\nconst MA_K = [{k:1, kx:'x'}, {k:2, kx:'2x'}, {k:0.5, kx:'0,5x'}, {k:3, kx:'3x'}, {k:Math.PI, kx:'πx'}, {k:Math.PI / 2, kx:'π/2 · x'}, {k:Math.PI / 3, kx:'π/3 · x'}, {k:Math.PI / 6, kx:'π/6 · x'}];\n\n/* Lineare Gleichungssysteme: Darstellung als ausgerichtete Tabelle, Stufenform mit ganzzahligen Zeilenumformungen */\nconst MA_ROEM = ['I', 'II', 'III', 'IV'];\nfunction maGlS(zeilen, vars, namen){\n  vars = vars || ['x', 'y', 'z']; namen = namen || MA_ROEM;\n  const td = 'style=\"padding:1px 4px;text-align:right;white-space:nowrap\"';\n  return '<table style=\"border-collapse:collapse;margin:6px 0;font-variant-numeric:tabular-nums\">' + zeilen.map((z, i) => {\n    let erst = true; const zellen = vars.map((v, j) => { const k = z[j]; if (!k) return `<td ${td}><\/td>`;\n      const s = (erst ? (k < 0 ? '−' : '') : (k < 0 ? '− ' : '+ ')) + (Math.abs(k) === 1 ? '' : maZ(Math.abs(k))) + v; erst = false; return `<td ${td}>${s}<\/td>`; });\n    if (erst) zellen[vars.length - 1] = `<td ${td}>0<\/td>`;\n    return `<tr><td ${td}>${namen[i]}:<\/td>${zellen.join('')}<td ${td}>=<\/td><td ${td}>${maZ(z[vars.length])}<\/td><\/tr>`; }).join('') + '<\/table>';\n}\nfunction maGgt(a, b){ a = Math.abs(a); b = Math.abs(b); while (b) [a, b] = [b, a % b]; return a; }\nfunction maKuerzen(r){ const g = r.reduce((s, v) => maGgt(s, Math.round(v)), 0) || 1; const sg = (r.find(v => v) || 1) < 0 ? -1 : 1; return r.map(v => v / g * sg); }\n// Stufenform (3×3 oder 2×2) mit ganzzahligen Umformungen; liefert {M, schritte}\nfunction maStufe(M){\n  const r = M.map(z => z.slice()), schritte = [], n = r.length;\n  for (let c = 0; c < n - 1; c++){\n    let p = -1; r.forEach((z, i) => { if (i >= c && z[c] && (p < 0 || Math.abs(z[c]) < Math.abs(r[p][c]))) p = i; }); if (p < 0) continue;\n    if (p !== c){ [r[p], r[c]] = [r[c], r[p]]; schritte.push(`Zeilen ${MA_ROEM[c]} und ${MA_ROEM[p]} tauschen`); }\n    for (let i = c + 1; i < n; i++){ if (!r[i][c]) continue; const g = maGgt(r[c][c], r[i][c]), a = r[c][c] / g, b = r[i][c] / g;\n      r[i] = maKuerzen(r[i].map((v, j) => a * v - b * r[c][j])); schritte.push(`${a === 1 ? '' : a === -1 ? '−' : maZ(a) + ' · '}${MA_ROEM[i]} ${b < 0 ? '+' : '−'} ${Math.abs(b) === 1 ? '' : maZ(Math.abs(b)) + ' · '}${MA_ROEM[c]}`); }\n  }\n  return {M:r, schritte};\n}\n\n/* Gauß-Werkstatt: interaktives Umformen eines LGS per Klick (in Aufgabentexten einbettbar).\n   maWerkstatt(M, vars) liefert HTML; die Knöpfe rufen maWsAus / maWsTipp / maWsNeu (global). */\nfunction maWerkstatt(M, vars){\n  vars = vars || ['x', 'y', 'z'].slice(0, M[0].length - 1);\n  const n = M.length, opt = sel => MA_ROEM.slice(0, n).map((r, i) => `<option value=\"${i}\"${i === sel ? ' selected' : ''}>${r}<\/option>`).join('');\n  const st = 'style=\"width:3.6em;padding:2px 4px;font:inherit\"';\n  return `<div class=\"ma-ws\" data-start='${JSON.stringify(M)}' data-m='${JSON.stringify(M)}' data-v='${JSON.stringify(vars)}' style=\"border:1.5px dashed var(--linie,#ccc);border-radius:10px;padding:8px 12px;margin:8px 0;background:var(--karte,transparent)\">\n  <div style=\"font-weight:600;margin-bottom:4px\">Gauß-Werkstatt (zum Ausprobieren)<\/div>\n  <div class=\"ma-ws-sys\">${maGlS(M, vars)}<\/div>\n  <div class=\"ma-ws-ctl\" oninput=\"maWsVor(this)\" onchange=\"maWsVor(this)\" style=\"display:grid;grid-template-columns:auto 1fr;gap:4px 8px;align-items:center;margin:8px 0\">\n    <b>Schritt 1:<\/b><span>Zeile <select class=\"ma-ws-z\" style=\"font:inherit\">${opt(1)}<\/select> mal <input class=\"ma-ws-a\" type=\"number\" value=\"1\" ${st}><\/span>\n    <b>Schritt 2:<\/b><span>Zeile <select class=\"ma-ws-q\" style=\"font:inherit\">${opt(0)}<\/select> mal <input class=\"ma-ws-b\" type=\"number\" value=\"-1\" ${st}><\/span>\n    <b>Schritt 3:<\/b><span>beide Zeilen <b>addieren<\/b> <span style=\"font-size:.85em;color:var(--stumm,#666)\">(zum Abziehen in Schritt 2 eine negative Zahl wählen)<\/span><\/span>\n    <span><\/span><span class=\"ma-ws-vor\" style=\"font-size:.9em;color:var(--stumm,#666)\">→ Das Ergebnis ersetzt Zeile II:  neue II = 1 · II + (−1) · I<\/span><\/div>\n  <div style=\"display:flex;flex-wrap:wrap;gap:6px\"><button type=\"button\" style=\"padding:4px 10px;border-radius:6px;border:1px solid var(--linie,#bbb);background:var(--karte,#fff);color:inherit;cursor:pointer;font:inherit\" onclick=\"maWsAus(this)\">Ausführen<\/button><button type=\"button\" style=\"padding:4px 10px;border-radius:6px;border:1px solid var(--linie,#bbb);background:var(--karte,#fff);color:inherit;cursor:pointer;font:inherit\" onclick=\"maWsTausch(this)\">Zeilen tauschen<\/button><button type=\"button\" style=\"padding:4px 10px;border-radius:6px;border:1px solid var(--linie,#bbb);background:var(--karte,#fff);color:inherit;cursor:pointer;font:inherit\" onclick=\"maWsTipp(this)\">Tipp: nächster Schritt<\/button><button type=\"button\" style=\"padding:4px 10px;border-radius:6px;border:1px solid var(--linie,#bbb);background:var(--karte,#fff);color:inherit;cursor:pointer;font:inherit\" onclick=\"maWsNeu(this)\">Neu starten<\/button><\/div>\n  <div class=\"ma-ws-rech\" style=\"margin-top:6px\"><\/div><div class=\"ma-ws-info\" style=\"margin-top:4px;font-size:.9em\"><\/div><\/div>`;\n}\nfunction maWsDaten(el){ const w = el.closest('.ma-ws'); return {w, M:JSON.parse(w.dataset.m), V:JSON.parse(w.dataset.v)}; }\nfunction maWsWerte(w){ const q = w.querySelector.bind(w); return {z:+q('.ma-ws-z').value, s:+q('.ma-ws-q').value, a:+q('.ma-ws-a').value, f:+q('.ma-ws-b').value, op:1}; }\nfunction maWsVor(el){ const w = el.closest('.ma-ws'), {z, s, a, f, op} = maWsWerte(w);\n  w.querySelector('.ma-ws-vor').textContent = z === s ? 'Wähle in Schritt 1 und 2 zwei verschiedene Zeilen.' : `→ Das Ergebnis ersetzt Zeile ${MA_ROEM[z]}:  neue ${MA_ROEM[z]} = ${maWsF(a)} · ${MA_ROEM[z]} + ${maWsF(f)} · ${MA_ROEM[s]}`; }\nfunction maWsRest(M, V){   // was bis zur Stufenform noch fehlt, in Worten\n  const ziel = M.length === 3 ? 'Ziel ist die Stufenform: In Zeile II darf kein x mehr stehen, in Zeile III weder x noch y.' : 'Ziel ist die Stufenform: In Zeile II darf kein x mehr stehen.';\n  const offen = M.map((r, i) => ({i, v:V.slice(0, i).filter((_, j) => r[j])})).filter(o => o.i && o.v.length);\n  return ziel + (offen.length ? ' Noch zu tun: ' + offen.map(o => `in Zeile ${MA_ROEM[o.i]} muss ${o.v.join(' und ')} wegfallen`).join('; ') + '.' : ''); }\nfunction maWsF(v){ return v < 0 ? '(' + maZ(v) + ')' : maZ(v); }\nfunction maWsStufe(M){ return M.every((z, i) => z.slice(0, i).every(v => !v)); }\nfunction maWsAus(el){\n  const {w, M, V} = maWsDaten(el), q = w.querySelector.bind(w), {z, s, a, f, op} = maWsWerte(w);\n  if (z === s){ q('.ma-ws-info').textContent = 'Wähle in Schritt 1 und Schritt 2 zwei verschiedene Zeilen.'; return; }\n  if (!a){ q('.ma-ws-info').textContent = 'In Schritt 1 darf nicht mit 0 multipliziert werden – sonst geht die Gleichung verloren.'; return; }\n  const A = M[z].map(v => a * v), B = M[s].map(v => f * v), N = A.map((v, j) => v + op * B[j]);\n  const nm = [`${maWsF(a)} · ${MA_ROEM[z]}`, `+ ${maWsF(f)} · ${MA_ROEM[s]}`, `neue ${MA_ROEM[z]}`];\n  q('.ma-ws-rech').innerHTML = '<div style=\"font-size:.9em;color:var(--stumm,#666)\">So wird gerechnet (spaltenweise addieren):<\/div>' + maGlS([A, B], V, nm.slice(0, 2)).replace('<\/table>', '') .replace(/<\\/table>$/, '') + '<tr><td colspan=\"' + (V.length + 3) + '\" style=\"border-top:2px solid currentColor;padding:0\"><\/td><\/tr>' + maGlS([N], V, [nm[2]]).replace(/^<table[^>]*>/, '');\n  const gg = N.reduce((t, v) => maGgt(t, v), 0); let gek = '';\n  if (gg > 1){ for (let j = 0; j < N.length; j++) N[j] /= gg; gek = ` Die neue Zeile wurde durch ${gg} gekürzt.`; }\n  M[z] = N; w.dataset.m = JSON.stringify(M); q('.ma-ws-sys').innerHTML = maGlS(M, V).replace(`<tr><td style=\"padding:1px 4px;text-align:right;white-space:nowrap\">${MA_ROEM[z]}:<\/td>`, `<tr style=\"background:var(--linie2,#eef)\"><td style=\"padding:1px 4px;text-align:right;white-space:nowrap\">${MA_ROEM[z]}:<\/td>`);\n  const leer = M.find(r => r.slice(0, -1).every(v => !v));\n  q('.ma-ws-info').innerHTML = (leer ? (leer[leer.length - 1] ? '<b>Widerspruch 0 = ' + maZ(leer[leer.length - 1]) + ':<\/b> keine Lösung.' : '<b>Zeile 0 = 0:<\/b> unendlich viele Lösungen (eine Variable frei wählbar).')\n    : maWsStufe(M) ? '<b>Stufenform erreicht!<\/b> Jetzt von unten nach oben einsetzen.' : 'Die neue Zeile ' + MA_ROEM[z] + ' steht jetzt im System (markiert). ' + maWsRest(M, V)) + gek;\n}\nfunction maWsTipp(el){\n  const {w, M} = maWsDaten(el), q = w.querySelector.bind(w), n = M.length;\n  for (let c = 0; c < n - 1; c++) for (let i = c + 1; i < n; i++) if (M[i][c] && M[c][c]){\n    const g = maGgt(M[c][c], M[i][c]) * (M[c][c] < 0 ? -1 : 1), a = M[c][c] / g, f = -M[i][c] / g, v = ['x', 'y', 'z'][c];\n    q('.ma-ws-z').value = i; q('.ma-ws-q').value = c; q('.ma-ws-a').value = a; q('.ma-ws-b').value = f; q('.ma-ws-rech').innerHTML = ''; maWsVor(q('.ma-ws-z'));\n    q('.ma-ws-info').innerHTML = `Vorschlag: In Zeile ${MA_ROEM[i]} soll ${v} wegfallen. Zeile ${MA_ROEM[i]} mal ${maWsF(a)} und Zeile ${MA_ROEM[c]} mal ${maWsF(f)} – dann stehen vor ${v} die Zahlen ${maZ(a * M[i][c])} und ${maZ(f * M[c][c])}. Das sind Gegenzahlen – beim <b>Addieren<\/b> fällt ${v} weg. Mit „Ausführen“ anwenden.`; return; }\n  for (let c = 0; c < n - 1; c++) if (!M[c][c]) for (let i = c + 1; i < n; i++) if (M[i][c]){ q('.ma-ws-z').value = c; q('.ma-ws-q').value = i;\n    maWsVor(q('.ma-ws-z')); q('.ma-ws-info').innerHTML = `Vorschlag: In Zeile ${MA_ROEM[c]} fehlt ${['x', 'y', 'z'][c]}. Tausche die Zeilen ${MA_ROEM[c]} und ${MA_ROEM[i]} (in Schritt 1 und 2 eingestellt, Knopf „Zeilen tauschen“).`; return; }\n  q('.ma-ws-info').innerHTML = maWsStufe(M) ? 'Die Stufenform ist erreicht – kein weiterer Schritt nötig.' : 'Kein weiterer Schritt nötig.';\n}\nfunction maWsTausch(el){\n  const {w, M, V} = maWsDaten(el), q = w.querySelector.bind(w), z = +q('.ma-ws-z').value, s = +q('.ma-ws-q').value;\n  if (z === s){ q('.ma-ws-info').textContent = 'Wähle in Schritt 1 und Schritt 2 zwei verschiedene Zeilen.'; return; }\n  [M[z], M[s]] = [M[s], M[z]]; w.dataset.m = JSON.stringify(M); q('.ma-ws-sys').innerHTML = maGlS(M, V); q('.ma-ws-rech').innerHTML = '';\n  q('.ma-ws-info').innerHTML = `Zeilen ${MA_ROEM[z]} und ${MA_ROEM[s]} getauscht – die Lösung ändert sich dadurch nicht.` + (maWsStufe(M) ? ' <b>Stufenform erreicht!<\/b>' : '');\n}\nfunction maWsNeu(el){ const w = el.closest('.ma-ws'); w.dataset.m = w.dataset.start; const M = JSON.parse(w.dataset.m);\n  w.querySelector('.ma-ws-sys').innerHTML = maGlS(M, JSON.parse(w.dataset.v)); w.querySelector('.ma-ws-rech').innerHTML = ''; w.querySelector('.ma-ws-info').innerHTML = ''; }\n/* ---------- Labor & Werkstatt: Kern (Navigation, Regler, Schaubilder, Aufträge) ----------\n   Ein Labor: labor({id, fach, titel, intro, bau(L)}) – bau baut die Oberfläche in L.links (Werkstatt) und L.rechts (Regler, Aufträge)\n   und meldet Aufträge mit L.auftraege([{t, ok:() => bool}]); nach jeder Änderung L.pruefen() aufrufen. */\nconst LABORE = [];\nfunction labor(def){ LABORE.push(def); }\nconst FAECHER = ['Mathematik', 'Buchführung und KLR', 'BWL, Investition und Finanzierung', 'Volkswirtschaft'];\n\n/* Zahlen */\nconst zf = (v, d) => { if (!Number.isFinite(v)) return '–'; const f = Math.pow(10, d == null ? 2 : d), r = Math.round(v * f) / f; return (r < 0 ? '−' : '') + Math.abs(r).toLocaleString('de-DE', {maximumFractionDigits:d == null ? 2 : d}); };\nconst ze = v => zf(v, 2).replace(/,(\\d)$/, ',$10') + ' €';   // Euro mit zwei Nachkommastellen\nconst zeG = v => (v < 0 ? '−' : '') + Math.abs(Math.round(v)).toLocaleString('de-DE') + ' €';\nconst nah = (a, b, t) => Math.abs(a - b) <= (t == null ? 1e-9 : t);\nconst runde = (v, d) => { const f = Math.pow(10, d == null ? 2 : d); return Math.round(v * f) / f; };\n\n/* DOM */\nfunction h(tag, attr, ...kinder){\n  const e = document.createElement(tag);\n  for (const [k, v] of Object.entries(attr || {})){ if (v == null || v === false) continue;\n    if (k === 'class') e.className = v; else if (k === 'html') e.innerHTML = v; else if (k.startsWith('on')) e.addEventListener(k.slice(2), v); else e.setAttribute(k, v === true ? '' : v); }\n  kinder.flat().forEach(k => { if (k == null || k === false) return; e.appendChild(typeof k === 'string' || typeof k === 'number' ? document.createTextNode(String(k)) : k); });\n  return e;\n}\nconst svgNS = 'http://www.w3.org/2000/svg';\n\n/* Regler: regler(eltern, {t, min, max, step, wert, fmt}) → {wert, setze(v)}; onInput wird nach jeder Änderung aufgerufen */\nfunction regler(eltern, o, onInput){\n  const id = 'r' + Math.random().toString(36).slice(2, 8), out = h('output', {for:id}), inp = h('input', {type:'range', id, min:o.min, max:o.max, step:o.step || 1, value:o.wert, 'aria-label':o.t});\n  const box = h('div', {class:'regler'}, h('label', {for:id, html:o.t}), out, inp);\n  const R = {get wert(){ return +inp.value; }, setze(v){ inp.value = v; zeige(); }, el:inp};\n  const zeige = () => { out.innerHTML = o.fmt ? o.fmt(+inp.value) : zf(+inp.value); };\n  inp.addEventListener('input', () => { zeige(); onInput && onInput(); });\n  zeige(); eltern.appendChild(box); return R;\n}\nfunction zahlFeld(eltern, t, wert, onInput, attr){\n  const inp = h('input', Object.assign({type:'number', value:wert, step:'any'}, attr || {}));\n  inp.addEventListener('input', () => onInput && onInput());\n  eltern.appendChild(h('label', {class:'feld'}, h('span', {html:t}), inp)); return {get wert(){ return +inp.value; }, setze(v){ inp.value = v; }, el:inp};\n}\nfunction auswahl(eltern, t, optionen, onChange){\n  const sel = h('select', {style:'padding:3px 6px;border:1px solid var(--linie);border-radius:6px'}, optionen.map((o, i) => h('option', {value:i}, o)));\n  sel.addEventListener('change', () => onChange && onChange(+sel.value));\n  eltern.appendChild(h('label', {class:'feld'}, h('span', {html:t}), sel)); return {get wert(){ return +sel.value; }, setze(v){ sel.value = v; }, el:sel};\n}\n\n/* Schaubild: plot(svg, {x0, x1, y0, y1, xs, ys, xt, yt, kurven:[{f, farbe, breite, strich, name}], punkte:[{x, y, farbe, r, t}], linien:[…], flaechen:[{pts, farbe, deckung}], texte:[{x, y, t, farbe}]}) */\nfunction plot(svg, o){\n  const W = 600, H = 380, l = 52, r = 14, t = 14, b = 34, pw = W - l - r, ph = H - t - b;\n  const X = x => l + (x - o.x0) / (o.x1 - o.x0) * pw, Y = y => t + ph - (y - o.y0) / (o.y1 - o.y0) * ph;\n  const xs = o.xs || 1, ys = o.ys || 1, fx = o.fx || (v => zf(v)), fy = o.fy || (v => zf(v));\n  let s = '';\n  for (let x = Math.ceil(o.x0 / xs - 1e-9) * xs; x <= o.x1 + 1e-9; x += xs) s += `<line x1=\"${X(x)}\" x2=\"${X(x)}\" y1=\"${t}\" y2=\"${t + ph}\" stroke=\"currentColor\" stroke-opacity=\".1\"/><text x=\"${X(x)}\" y=\"${t + ph + 15}\" font-size=\"11\" text-anchor=\"middle\" fill=\"currentColor\" fill-opacity=\".75\">${fx(x)}<\/text>`;\n  for (let y = Math.ceil(o.y0 / ys - 1e-9) * ys; y <= o.y1 + 1e-9; y += ys) s += `<line x1=\"${l}\" x2=\"${l + pw}\" y1=\"${Y(y)}\" y2=\"${Y(y)}\" stroke=\"currentColor\" stroke-opacity=\".1\"/><text x=\"${l - 6}\" y=\"${Y(y) + 4}\" font-size=\"11\" text-anchor=\"end\" fill=\"currentColor\" fill-opacity=\".75\">${fy(y)}<\/text>`;\n  if (o.y0 <= 0 && o.y1 >= 0) s += `<line x1=\"${l}\" x2=\"${l + pw}\" y1=\"${Y(0)}\" y2=\"${Y(0)}\" stroke=\"currentColor\" stroke-width=\"1.2\"/>`;\n  if (o.x0 <= 0 && o.x1 >= 0) s += `<line x1=\"${X(0)}\" x2=\"${X(0)}\" y1=\"${t}\" y2=\"${t + ph}\" stroke=\"currentColor\" stroke-width=\"1.2\"/>`;\n  if (o.xt) s += `<text x=\"${l + pw}\" y=\"${H - 2}\" font-size=\"12\" text-anchor=\"end\" fill=\"currentColor\">${o.xt}<\/text>`;\n  if (o.yt) s += `<text x=\"12\" y=\"${t + 4}\" font-size=\"12\" fill=\"currentColor\" transform=\"rotate(-90 12 ${t + 4}) translate(-${ph / 2} 0)\">${o.yt}<\/text>`;\n  let inner = '';\n  (o.flaechen || []).forEach(F => { inner += `<polygon points=\"${F.pts.map(p => X(p[0]).toFixed(1) + ',' + Y(p[1]).toFixed(1)).join(' ')}\" fill=\"${F.farbe}\" fill-opacity=\"${F.deckung == null ? .25 : F.deckung}\" stroke=\"${F.rand || 'none'}\" stroke-width=\"1\"/>`; });\n  (o.kurven || []).forEach(K => { const pts = [], n = 300; for (let j = 0; j <= n; j++){ const x = o.x0 + (o.x1 - o.x0) * j / n, y = K.f(x);\n      if (Number.isFinite(y)) pts.push(X(x).toFixed(1) + ',' + Y(Math.max(Math.min(y, o.y1 + 3 * (o.y1 - o.y0)), o.y0 - 3 * (o.y1 - o.y0))).toFixed(1)); }\n    inner += `<polyline points=\"${pts.join(' ')}\" fill=\"none\" stroke=\"${K.farbe || 'var(--rot)'}\" stroke-width=\"${K.breite || 2.4}\" ${K.strich ? `stroke-dasharray=\"${K.strich}\"` : ''}/>`; });\n  (o.linien || []).forEach(L => { inner += `<line x1=\"${X(L.x1)}\" y1=\"${Y(L.y1)}\" x2=\"${X(L.x2)}\" y2=\"${Y(L.y2)}\" stroke=\"${L.farbe || 'currentColor'}\" stroke-width=\"${L.breite || 1.5}\" ${L.strich ? `stroke-dasharray=\"${L.strich}\"` : ''}/>`; });\n  let oben = '';\n  (o.punkte || []).forEach(P => { oben += `<circle cx=\"${X(P.x)}\" cy=\"${Y(P.y)}\" r=\"${P.r || 4.5}\" fill=\"${P.farbe || 'currentColor'}\"/>` + (P.t ? `<text x=\"${X(P.x) + 7}\" y=\"${Y(P.y) - 7}\" font-size=\"12\" font-weight=\"600\" fill=\"${P.farbe || 'currentColor'}\">${P.t}<\/text>` : ''); });\n  (o.texte || []).forEach(T => { oben += `<text x=\"${X(T.x)}\" y=\"${Y(T.y)}\" font-size=\"12.5\" font-weight=\"700\" fill=\"${T.farbe || 'currentColor'}\" text-anchor=\"${T.anker || 'start'}\">${T.t}<\/text>`; });\n  svg.setAttribute('viewBox', `0 0 ${W} ${H}`);\n  svg.innerHTML = s + `<svg x=\"${l}\" y=\"${t}\" width=\"${pw}\" height=\"${ph}\" viewBox=\"${l} ${t} ${pw} ${ph}\" overflow=\"hidden\">${inner}<\/svg>` + oben;\n  return {X, Y};\n}\nfunction neuesSvg(eltern){ const s = document.createElementNS(svgNS, 'svg'); s.setAttribute('class', 'plot'); s.setAttribute('role', 'img'); eltern.appendChild(s); return s; }\n\n/* Seite */\nlet AKTIV = null;\nconst ERLEDIGT = {};   // id → Set der erledigten Auftragsnummern (bleibt beim Zurücksetzen und beim Wechsel des Labors erhalten)\nconst FORTLAUFEND = ['netzplan', 'tilgung', 'halbierung', 'tangente', 'gauss', 'tkonten', 'bab'];   // Aufträge bauen aufeinander auf → kein Zurücksetzen\nfunction zeigeLabor(id, opt){\n  const def = LABORE.find(d => d.id === id) || LABORE[0]; AKTIV = def.id;\n  const fortlaufend = def.fortlaufend != null ? def.fortlaufend : FORTLAUFEND.includes(def.id);\n  const fertigSet = ERLEDIGT[def.id] || (ERLEDIGT[def.id] = new Set());\n  document.querySelectorAll('.navi a').forEach(a => a.classList.toggle('aktiv', a.dataset.id === def.id));\n  const haupt = document.getElementById('haupt'); haupt.innerHTML = '';\n  const kopf = h('div', {class:'karte'}, h('div', {class:'augenbraue'}, def.fach), h('h2', {class:'lab-titel'}, def.titel), h('p', {class:'lab-intro', html:def.intro}));\n  const links = h('div', {class:'karte'}), rechts = h('div', {class:'karte'});\n  const ablage = h('div');\n  if (def.breit) haupt.append(kopf, h('div', {class:'lab-grid'}, rechts, ablage), links); else haupt.append(kopf, h('div', {class:'lab-grid'}, links, h('div', {}, rechts, ablage)));\n  const liste = h('ul', {class:'auftraege'}), fertig = h('div', {class:'fertig'}, '✓ Alle Aufträge erledigt – stark!'), meldung = h('div', {class:'weiter-meldung'});\n  let A = [], aktuell = -1, bereit = false;\n  const naechster = ab => { for (let k = 1; k <= A.length; k++){ const j = (ab + k) % A.length; if (!A[j].erledigt) return j; } return -1; };\n  const markiere = i => { aktuell = i; A.forEach((x, j) => x.li.classList.toggle('aktuell', j === i)); };\n  const weiter = () => zeigeLabor(def.id, {aktuell:naechster(aktuell < 0 ? -1 : aktuell)});\n  const L = {links, rechts,\n    auftraege(a){ A = a.map((x, i) => Object.assign({erledigt:fertigSet.has(i)}, x));\n      const kopfA = h('div', {class:'auftrag-kopf'}, h('div', {class:'augenbraue'}, 'Aufträge'),\n        fortlaufend ? null : h('button', {class:'knopf klein', title:'Alle Regler und Eingaben auf die Startwerte setzen – erledigte Aufträge bleiben abgehakt', onclick:() => zeigeLabor(def.id, {aktuell})}, '↺ Startwerte'));\n      const hinweis = h('div', {class:'legende'}, fortlaufend ? 'Die Aufträge bauen aufeinander auf – arbeite sie von oben nach unten ab.' : 'Die Aufträge sind unabhängig voneinander. Ein erledigter Auftrag bleibt abgehakt; mit „Nächster Auftrag“ startest du wieder bei den Startwerten.');\n      ablage.appendChild(h('div', {class:'karte'}, kopfA, hinweis, liste, meldung, fertig));\n      liste.innerHTML = ''; A.forEach((x, i) => { x.li = h('li', {onclick:() => { if (!x.erledigt) markiere(i); }}, h('span', {class:'haken'}, x.erledigt ? '✓' : String(i + 1)), h('span', {html:x.t})); if (x.erledigt) x.li.classList.add('erledigt'); liste.appendChild(x.li); });\n      const start = opt && opt.aktuell != null && opt.aktuell >= 0 && !A[opt.aktuell].erledigt ? opt.aktuell : naechster(-1);\n      markiere(start); L.pruefen(); },\n    pruefen(){ let neu = -1;\n      A.forEach((x, i) => { if (!x.erledigt){ let ok = false; try { ok = !!x.ok(); } catch(e){} if (ok){ x.erledigt = true; fertigSet.add(i); x.li.classList.add('erledigt'); x.li.querySelector('.haken').textContent = '✓'; if (neu < 0) neu = i; } } });\n      const alle = A.length > 0 && A.every(x => x.erledigt);\n      fertig.classList.toggle('an', alle);\n      if (neu >= 0 && bereit){ meldung.innerHTML = ''; meldung.classList.add('an');\n        if (fortlaufend){ const n = naechster(neu); markiere(n); meldung.append(h('span', {}, `✓ Auftrag ${neu + 1} erledigt!` + (n >= 0 ? ` Weiter mit Auftrag ${n + 1}.` : ''))); }\n        else { markiere(neu); meldung.append(h('span', {}, `✓ Auftrag ${neu + 1} erledigt!`));\n          if (!alle) meldung.append(h('button', {class:'knopf primaer', onclick:weiter}, 'Nächster Auftrag (Regler auf Start) →'), h('button', {class:'knopf', onclick:() => { meldung.classList.remove('an'); markiere(naechster(neu)); }}, 'Hier weiter ausprobieren'));\n          else meldung.append(h('button', {class:'knopf', onclick:() => zeigeLabor(def.id)}, '↺ Startwerte')); }\n      }\n      const a = document.querySelector(`.navi a[data-id=\"${def.id}\"] .fort`); if (a) a.textContent = fertigSet.size + '/' + A.length;\n      soloMelden({labor:def.id, erledigt:fertigSet.size, gesamt:A.length, fertig:alle}); }};\n  def.bau(L); bereit = true;\n  if (!SOLO && location.hash.slice(1) !== def.id) try { history.replaceState(null, '', '#' + def.id); } catch(e){}\n  if (!opt) window.scrollTo && window.scrollTo(0, 0);\n}\nfunction start(){\n  const nav = document.getElementById('navi');\n  FAECHER.forEach(f => { const ls = LABORE.filter(d => d.fach === f); if (!ls.length) return; nav.appendChild(h('h3', {}, f));\n    ls.forEach(d => nav.appendChild(h('a', {href:'#' + d.id, 'data-id':d.id, onclick:e => { e.preventDefault(); zeigeLabor(d.id); }}, h('span', {}, d.titel), h('span', {class:'fort'}, '')))); });\n  window.addEventListener('hashchange', () => { if (location.hash.slice(1) !== AKTIV) zeigeLabor(location.hash.slice(1)); });\n  zeigeLabor(location.hash.slice(1));\n}\n\n/* Einbettung in die Trainer: ein einzelnes Labor ohne Kopf und Navigation (window.LABOR_SOLO = id).\n   Fortschritt und Höhe gehen per postMessage an die Trainerseite. */\nconst SOLO = typeof window !== 'undefined' && window.LABOR_SOLO ? window.LABOR_SOLO : null;\nfunction soloMelden(d){ if (SOLO && window.parent && window.parent !== window) try { window.parent.postMessage(Object.assign({quelle:'labor'}, d), '*'); } catch(e){} }\nfunction startSolo(id){\n  document.body.classList.add('solo');\n  zeigeLabor(id);\n  const hoehe = () => soloMelden({labor:id, hoehe:Math.ceil(document.documentElement.scrollHeight)});\n  if (window.ResizeObserver) new ResizeObserver(hoehe).observe(document.body); hoehe();\n}\n/* ---------- Labor: Mathematik ---------- */\nconst PI = Math.PI;\nfunction polyMal(a, b){ const r = new Array(a.length + b.length - 1).fill(0); a.forEach((x, i) => b.forEach((y, j) => r[i + j] += x * y)); return r; }   // Koeffizienten aufsteigend\nfunction polyText(k){   // k aufsteigend\n  let s = ''; for (let g = k.length - 1; g >= 0; g--){ const a = runde(k[g], 4); if (!a) continue; const b = Math.abs(a);\n    const z = g === 0 ? zf(b) : (b === 1 ? '' : zf(b)) + 'x' + (g > 1 ? ({2:'²', 3:'³', 4:'⁴', 5:'⁵', 6:'⁶', 7:'⁷', 8:'⁸', 9:'⁹'}[g]) : '');\n    s += s ? (a < 0 ? ' − ' : ' + ') + z : (a < 0 ? '−' : '') + z; }\n  return s || '0';\n}\nconst piText = v => { for (let d = 1; d <= 12; d++){ const n = Math.round(v / PI * d); if (Math.abs(n * PI / d - v) < 1e-9){ if (!n) return '0'; const g = maGgt(n, d), z = n / g, q = d / g; return (z < 0 ? '−' : '') + (Math.abs(z) === 1 ? '' : Math.abs(z)) + 'π' + (q === 1 ? '' : '/' + q); } } return zf(v); };\n\n/* ======================= Funktions-Labor ======================= */\nlabor({id:'funktionen', fach:'Mathematik', titel:'Funktions-Labor: Parameter verstehen',\n  intro:'Verändere die Parameter mit den Reglern und beobachte, wie sich das Schaubild verändert. Grau gestrichelt siehst du die Grundfunktion. Erfülle die Aufträge – sie haken sich automatisch ab.',\n  bau(L){\n    const typen = ['Parabel a(x − d)² + e', 'e-Funktion a · e<sup>kx<\/sup> + b', 'Sinus a · sin(kx) + b', 'Kosinus a · cos(kx) + b'];\n    const term = h('div', {class:'term'}), svg = neuesSvg(L.links), eig = h('div', {class:'info'});\n    L.links.prepend(term); L.links.append(eig);\n    const typW = auswahl(L.rechts, 'Funktionstyp', ['Parabel', 'e-Funktion', 'Sinus', 'Kosinus'], () => baueRegler());\n    const box = h('div'); L.rechts.append(box);\n    let R = {}, typ = 0;\n    const st = () => ({typ, a:R.a.wert, p:R.p.wert, q:R.q.wert});\n    function baueRegler(){\n      typ = typW.wert; box.innerHTML = '';\n      if (typ === 0){ R.a = regler(box, {t:'Streckfaktor a', min:-3, max:3, step:0.25, wert:1}, zeichne); R.p = regler(box, {t:'Verschiebung d (x-Richtung)', min:-4, max:4, step:0.5, wert:0}, zeichne); R.q = regler(box, {t:'Verschiebung e (y-Richtung)', min:-5, max:5, step:0.5, wert:0}, zeichne); }\n      else if (typ === 1){ R.a = regler(box, {t:'Faktor a', min:-4, max:4, step:0.5, wert:1}, zeichne); R.p = regler(box, {t:'k im Exponenten', min:-2, max:2, step:0.25, wert:1}, zeichne); R.q = regler(box, {t:'Verschiebung b (Asymptote)', min:-4, max:4, step:0.5, wert:0}, zeichne); }\n      else { R.a = regler(box, {t:'Amplitude a', min:-4, max:4, step:0.5, wert:1}, zeichne); R.p = regler(box, {t:'k (Periode 2π/k)', min:0.5, max:4, step:0.5, wert:1}, zeichne); R.q = regler(box, {t:'Verschiebung b (Mittellinie)', min:-3, max:3, step:0.5, wert:0}, zeichne); }\n      zeichne();\n    }\n    function zeichne(){\n      const s = st(), a = s.a, p = s.p, q = s.q; let f, g, txt, info;\n      if (typ === 0){ f = x => a * (x - p) * (x - p) + q; g = x => x * x;\n        txt = `f(x) = ${a === 1 ? '' : a === -1 ? '−' : zf(a)}${p ? '(x ' + (p > 0 ? '− ' + zf(p) : '+ ' + zf(-p)) + ')²' : 'x²'}${q ? (q > 0 ? ' + ' : ' − ') + zf(Math.abs(q)) : ''}`;\n        info = a ? `Scheitel S(${zf(p)} | ${zf(q)}); ${a > 0 ? 'nach oben' : 'nach unten'} geöffnet; ${Math.abs(a) > 1 ? 'schmaler' : Math.abs(a) < 1 ? 'breiter' : 'so breit'} als die Normalparabel.` : 'a = 0: keine Parabel mehr, sondern die waagrechte Gerade y = e.'; }\n      else if (typ === 1){ f = x => a * Math.exp(p * x) + q; g = x => Math.exp(x);\n        txt = `f(x) = ${a === 1 ? '' : a === -1 ? '−' : zf(a) + ' · '}e<sup>${p === 1 ? '' : p === -1 ? '−' : zf(p)}x<\/sup>${q ? (q > 0 ? ' + ' : ' − ') + zf(Math.abs(q)) : ''}`;\n        info = a && p ? `Asymptote y = ${zf(q)} (für x → ${p > 0 ? '−∞' : '+∞'}); S<sub>y<\/sub>(0 | ${zf(a + q)}); ${a * p > 0 ? 'steigend' : 'fallend'}.` : 'Mit a = 0 oder k = 0 ist f konstant.'; }\n      else { const fn = typ === 2 ? Math.sin : Math.cos; f = x => a * fn(p * x) + q; g = x => fn(x);\n        txt = `f(x) = ${a === 1 ? '' : a === -1 ? '−' : zf(a)}${typ === 2 ? 'sin' : 'cos'}(${p === 1 ? '' : zf(p)}x)${q ? (q > 0 ? ' + ' : ' − ') + zf(Math.abs(q)) : ''}`;\n        info = `Amplitude ${zf(Math.abs(a))}; Periode 2π/${zf(p)} ≈ ${zf(2 * PI / p)}; Mittellinie y = ${zf(q)}; Wertemenge [${zf(q - Math.abs(a))}; ${zf(q + Math.abs(a))}].`; }\n      term.innerHTML = txt; eig.innerHTML = info;\n      const trig = typ >= 2;\n      plot(svg, trig ? {x0:-PI, x1:2 * PI, y0:-6, y1:6, xs:PI / 2, fx:piText, kurven:[{f:g, farbe:'var(--stumm)', breite:1.5, strich:'5 4'}, {f}]}\n                     : {x0:-6, x1:6, y0:-6, y1:8, kurven:[{f:g, farbe:'var(--stumm)', breite:1.5, strich:'5 4'}, {f}],\n                        linien:typ === 1 ? [{x1:-6, y1:q, x2:6, y2:q, farbe:'var(--blau)', strich:'6 4'}] : [], punkte:typ === 0 && a ? [{x:p, y:q, farbe:'var(--rot)', t:'S'}] : []});\n      L.pruefen();\n    }\n    baueRegler();\n    L.auftraege([\n      {t:'Parabel: Stelle den Scheitel auf <b>S(2 | −1)<\/b>.', ok:() => typ === 0 && R.p.wert === 2 && R.q.wert === -1 && R.a.wert !== 0},\n      {t:'Parabel: <b>nach unten geöffnet<\/b> und <b>schmaler<\/b> als die Normalparabel.', ok:() => typ === 0 && R.a.wert < -1},\n      {t:'Parabel mit <b>genau einer Nullstelle<\/b>, deren Scheitel <b>nicht<\/b> im Ursprung liegt.', ok:() => typ === 0 && R.q.wert === 0 && R.p.wert !== 0 && R.a.wert !== 0},\n      {t:'e-Funktion: <b>fallend<\/b> mit der Asymptote <b>y = 2<\/b>.', ok:() => typ === 1 && R.q.wert === 2 && R.a.wert * R.p.wert < 0},\n      {t:'e-Funktion durch <b>S(0 | 5)<\/b> mit Asymptote <b>y = 1<\/b>.', ok:() => typ === 1 && R.q.wert === 1 && R.a.wert + R.q.wert === 5 && R.p.wert !== 0},\n      {t:'Sinus mit <b>Periode π<\/b> und <b>Amplitude 3<\/b>.', ok:() => typ === 2 && R.p.wert === 2 && Math.abs(R.a.wert) === 3},\n      {t:'Kosinus mit der Wertemenge <b>[−1; 3]<\/b>.', ok:() => typ === 3 && R.q.wert === 1 && Math.abs(R.a.wert) === 2}\n    ]);\n  }});\n\n/* ======================= Nullstellen-Baukasten ======================= */\nlabor({id:'nullstellen', fach:'Mathematik', titel:'Nullstellen-Baukasten',\n  intro:'Setze Nullstellen und ihre Vielfachheit. Der Trainer baut daraus die Polynomfunktion in Produktform und ausmultipliziert. Achte darauf, wie sich das Schaubild an einfachen, doppelten und dreifachen Nullstellen verhält.',\n  bau(L){\n    const term1 = h('div', {class:'term'}), term2 = h('div', {class:'term', style:'font-size:1rem'}), svg = neuesSvg(L.links), info = h('div', {class:'info'});\n    L.links.prepend(term1, h('br'), term2); L.links.append(info);\n    const A = regler(L.rechts, {t:'Faktor a', min:-2, max:2, step:0.25, wert:0.5}, zeichne);\n    const N = [[-1, 1], [3, 1], [0, 0]].map(([x, m], i) => { const box = h('div', {style:'border-top:1px solid var(--linie2);padding-top:.3rem;margin-top:.3rem'}); L.rechts.append(box);\n      return {x:regler(box, {t:`Nullstelle ${i + 1}: Lage`, min:-4, max:4, step:1, wert:x}, zeichne), m:auswahl(box, 'Vielfachheit', ['aus', 'einfach', 'doppelt', 'dreifach'], zeichne)}; });\n    N.forEach((n, i) => n.m.setze([1, 1, 0][i]));\n    let K = [1];\n    function zeichne(){\n      const a = A.wert || 0.25, aktiv = N.filter(n => n.m.wert > 0);\n      K = [a]; aktiv.forEach(n => { for (let j = 0; j < n.m.wert; j++) K = polyMal(K, [-n.x.wert, 1]); });\n      const f = x => K.reduce((s, c, i) => s + c * Math.pow(x, i), 0), grad = K.length - 1;\n      term1.innerHTML = 'f(x) = ' + (a === 1 ? '' : a === -1 ? '−' : zf(a)) + (aktiv.map(n => { const r = n.x.wert, b = r === 0 ? 'x' : `(x ${r > 0 ? '− ' + r : '+ ' + -r})`; return b + (n.m.wert > 1 ? ({2:'²', 3:'³'})[n.m.wert] : ''); }).join(' · ') || '');\n      term2.innerHTML = 'ausmultipliziert: f(x) = ' + polyText(K);\n      let lo = Infinity, hi = -Infinity; for (let j = 0; j <= 200; j++){ const y = f(-5 + j / 20); lo = Math.min(lo, y); hi = Math.max(hi, y); }\n      const y0 = Math.max(lo, -12), y1 = Math.min(hi, 12), sp = Math.max(y1 - y0, 4), ys = sp > 16 ? 2 : 1;\n      plot(svg, {x0:-5, x1:5, y0:Math.floor(y0) - 1, y1:Math.ceil(y1) + 1, ys, kurven:[{f}],\n        punkte:aktiv.map(n => ({x:n.x.wert, y:0, farbe:['', 'var(--blau)', 'var(--moos)', 'var(--gold)'][n.m.wert], t:['', 'einfach', 'doppelt', 'dreifach'][n.m.wert]}))});\n      const doppelt = new Set(aktiv.map(n => n.x.wert)).size < aktiv.length;\n      info.innerHTML = doppelt ? 'Zwei Nullstellen liegen an derselben Stelle – ihre Vielfachheiten addieren sich.' : `Grad ${grad}; ${a > 0 ? 'Leitkoeffizient positiv' : 'Leitkoeffizient negativ'}: ${grad % 2 ? (a > 0 ? 'von links unten nach rechts oben' : 'von links oben nach rechts unten') : (a > 0 ? 'beide Enden oben' : 'beide Enden unten')}; y-Achsenabschnitt f(0) = ${zf(K[0])}. Einfach: Schnittpunkt · doppelt: Berührpunkt · dreifach: Sattelpunkt.`.replace(/ · /g, '; ');\n      L.pruefen();\n    }\n    const ns = () => N.filter(n => n.m.wert > 0).map(n => ({x:n.x.wert, m:n.m.wert})), grad = () => K.length - 1, eind = () => new Set(ns().map(n => n.x)).size === ns().length;\n    zeichne();\n    L.auftraege([\n      {t:'Grad 3 mit einem <b>Berührpunkt bei x = 2<\/b> und einem <b>Schnittpunkt bei x = −1<\/b>.', ok:() => eind() && grad() === 3 && ns().some(n => n.x === 2 && n.m === 2) && ns().some(n => n.x === -1 && n.m === 1)},\n      {t:'Ein <b>Sattelpunkt im Ursprung<\/b> (dreifache Nullstelle bei 0), sonst keine Nullstelle.', ok:() => eind() && ns().length === 1 && ns()[0].x === 0 && ns()[0].m === 3},\n      {t:'Grad 4, <b>beide Enden unten<\/b>, mit <b>zwei Berührpunkten<\/b>.', ok:() => eind() && grad() === 4 && A.wert < 0 && ns().filter(n => n.m === 2).length === 2},\n      {t:'Grad 3 mit drei verschiedenen Nullstellen und dem <b>y-Achsenabschnitt 6<\/b>.', ok:() => eind() && grad() === 3 && ns().length === 3 && nah(K[0], 6, 1e-9)}\n    ]);\n  }});\n\n/* ======================= Einheitskreis ======================= */\nlabor({id:'einheitskreis', fach:'Mathematik', titel:'Einheitskreis und Sinuskurve',\n  intro:'Drehe den Punkt auf dem Einheitskreis. Die <span style=\"color:var(--blau)\">x-Koordinate<\/span> ist cos(α), die <span style=\"color:var(--rot)\">y-Koordinate<\/span> ist sin(α). Rechts entsteht daraus die Sinuskurve.',\n  bau(L){\n    const reihe = h('div', {style:'display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.6fr);gap:.6rem;align-items:center'}); L.links.append(reihe);\n    const kreis = document.createElementNS(svgNS, 'svg'); kreis.setAttribute('viewBox', '0 0 300 300'); kreis.setAttribute('class', 'plot'); reihe.append(kreis);\n    const kurve = neuesSvg(reihe), werte = h('div', {class:'info'}); L.links.append(werte);\n    const W = regler(L.rechts, {t:'Winkel α', min:0, max:24, step:1, wert:2, fmt:v => `${v * 15}° = ${piText(v * PI / 12)}`}, zeichne);\n    const ex = v => { const t = [[0, '0'], [0.5, '½'], [Math.SQRT2 / 2, '½√2'], [Math.sqrt(3) / 2, '½√3'], [1, '1']].find(p => nah(Math.abs(v), p[0], 1e-9)); return t ? (v < -1e-12 ? '−' : '') + t[1] : zf(v); };\n    function zeichne(){\n      const a = W.wert * PI / 12, c = Math.cos(a), s = Math.sin(a), M = 150, R = 110, px = M + R * c, py = M - R * s;\n      kreis.innerHTML = `<line x1=\"20\" x2=\"280\" y1=\"150\" y2=\"150\" stroke=\"currentColor\" stroke-opacity=\".4\"/><line x1=\"150\" x2=\"150\" y1=\"20\" y2=\"280\" stroke=\"currentColor\" stroke-opacity=\".4\"/>\n        <circle cx=\"150\" cy=\"150\" r=\"110\" fill=\"none\" stroke=\"currentColor\" stroke-opacity=\".6\"/>\n        <path d=\"M ${M + 28} ${M} A 28 28 0 ${a > PI ? 1 : 0} 0 ${M + 28 * c} ${M - 28 * s}\" fill=\"none\" stroke=\"var(--gold)\" stroke-width=\"2\"/>\n        <line x1=\"${M}\" y1=\"${M}\" x2=\"${px}\" y2=\"${py}\" stroke=\"currentColor\" stroke-width=\"1.5\"/>\n        <line x1=\"${M}\" y1=\"${M}\" x2=\"${px}\" y2=\"${M}\" stroke=\"var(--blau)\" stroke-width=\"4\"/>\n        <line x1=\"${px}\" y1=\"${M}\" x2=\"${px}\" y2=\"${py}\" stroke=\"var(--rot)\" stroke-width=\"4\"/>\n        <circle cx=\"${px}\" cy=\"${py}\" r=\"6\" fill=\"var(--tinte)\"/><text x=\"262\" y=\"145\" font-size=\"12\">x<\/text><text x=\"155\" y=\"30\" font-size=\"12\">y<\/text>\n        <text x=\"270\" y=\"166\" font-size=\"11\">1<\/text><text x=\"154\" y=\"44\" font-size=\"11\">1<\/text>`;\n      plot(kurve, {x0:0, x1:2 * PI, y0:-1.3, y1:1.3, xs:PI / 2, ys:0.5, fx:piText, kurven:[{f:Math.sin, farbe:'var(--stumm)', breite:1.2, strich:'4 4'}, {f:x => x <= a + 1e-9 ? Math.sin(x) : NaN, farbe:'var(--rot)'}],\n        linien:[{x1:a, y1:0, x2:a, y2:s, farbe:'var(--rot)', breite:3}], punkte:[{x:a, y:s, farbe:'var(--tinte)'}]});\n      werte.innerHTML = `α = ${W.wert * 15}° = ${piText(a)} ≈ ${zf(a)}<br><b style=\"color:var(--blau)\">cos(α) = ${ex(c)}<\/b> ≈ ${zf(c)} · <b style=\"color:var(--rot)\">sin(α) = ${ex(s)}<\/b> ≈ ${zf(s)}<br>Quadrant: ${W.wert % 6 === 0 ? 'auf einer Achse' : ['I', 'II', 'III', 'IV'][Math.floor(W.wert / 6) % 4]}`.replace(' · ', '; ');\n      L.pruefen();\n    }\n    zeichne();\n    L.auftraege([\n      {t:'Finde einen Winkel mit <b>sin(α) = ½<\/b> im <b>zweiten Quadranten<\/b>.', ok:() => W.wert === 10},\n      {t:'Finde den Winkel mit <b>cos(α) = −1<\/b>.', ok:() => W.wert === 12},\n      {t:'Finde einen Winkel im dritten Quadranten mit <b>sin(α) = cos(α)<\/b>.', ok:() => W.wert === 15},\n      {t:'Wo ist der <b>Sinus am kleinsten<\/b>?', ok:() => W.wert === 18}\n    ]);\n  }});\n\n/* ======================= Intervallhalbierung ======================= */\nlabor({id:'halbierung', fach:'Mathematik', titel:'Intervallhalbierung: Nullstelle einkreisen',\n  intro:'Manche Gleichungen kann man nicht exakt lösen. Hier kreist du die Nullstelle ein: Intervall halbieren, Vorzeichen in der Mitte prüfen, das Teilintervall mit Vorzeichenwechsel behalten.',\n  bau(L){\n    const F = [{t:'f(x) = x³ − 2x − 5', f:x => x * x * x - 2 * x - 5, a:2, b:3, x0:0, x1:3.5}, {t:'f(x) = cos(x) − x', f:x => Math.cos(x) - x, a:0, b:1, x0:-0.5, x1:2}, {t:'f(x) = e<sup>x<\/sup> + x − 2', f:x => Math.exp(x) + x - 2, a:0, b:1, x0:-1, x1:1.5}];\n    const term = h('div', {class:'term'}), svg = neuesSvg(L.links), tab = h('div', {class:'scroll'}), info = h('div', {class:'info'});\n    L.links.prepend(term); L.links.append(info, tab);\n    let a, b, schritte = [], fn;\n    const W = auswahl(L.rechts, 'Funktion', F.map(x => x.t.replace(/<[^>]+>/g, '')), neu);\n    const kn = h('div', {class:'knoepfe'}, h('button', {class:'knopf primaer', onclick:halb}, 'Intervall halbieren'), h('button', {class:'knopf', onclick:neu}, 'Neu starten'));\n    L.rechts.append(kn);\n    function neu(){ fn = F[W.wert]; a = fn.a; b = fn.b; schritte = []; zeichne(); }\n    function halb(){ const m = (a + b) / 2, fa = fn.f(a), fm = fn.f(m); schritte.push({a, b, m, fa, fm});\n      if (fa * fm <= 0) b = m; else a = m; zeichne(); }\n    function zeichne(){\n      term.innerHTML = fn.t;\n      plot(svg, {x0:fn.x0, x1:fn.x1, y0:-6, y1:6, xs:0.5, fx:v => zf(v, 1), flaechen:[{pts:[[a, -6], [b, -6], [b, 6], [a, 6]], farbe:'var(--gold)', deckung:.18}], kurven:[{f:fn.f}],\n        punkte:[{x:a, y:fn.f(a), farbe:'var(--blau)', t:'a'}, {x:b, y:fn.f(b), farbe:'var(--blau)', t:'b'}]});\n      info.innerHTML = `Aktuelles Intervall [${zf(a, 4)}; ${zf(b, 4)}], Breite ${zf(b - a, 4)}; f(a) ${fn.f(a) < 0 ? '< 0' : '> 0'}, f(b) ${fn.f(b) < 0 ? '< 0' : '> 0'}.`;\n      tab.innerHTML = schritte.length ? '<table class=\"lab\"><tr><th>Schritt<\/th><th>a<\/th><th>b<\/th><th>Mitte m<\/th><th>f(m)<\/th><th>weiter mit<\/th><\/tr>' +\n        schritte.map((s, i) => `<tr${i === schritte.length - 1 ? ' class=\"neu\"' : ''}><td>${i + 1}<\/td><td>${zf(s.a, 4)}<\/td><td>${zf(s.b, 4)}<\/td><td>${zf(s.m, 4)}<\/td><td>${zf(s.fm, 3)}<\/td><td>${s.fa * s.fm <= 0 ? 'linke Hälfte' : 'rechte Hälfte'}<\/td><\/tr>`).join('') + '<\/table>' : '';\n      L.pruefen();\n    }\n    neu();\n    L.auftraege([\n      {t:'Führe den ersten Halbierungsschritt durch.', ok:() => schritte.length >= 1},\n      {t:'Grenze die Nullstelle auf ein Intervall mit <b>Breite unter 0,1<\/b> ein.', ok:() => b - a < 0.1},\n      {t:'Bestimme die Nullstelle auf <b>zwei Nachkommastellen<\/b> (Breite unter 0,01).', ok:() => b - a < 0.01}\n    ]);\n  }});\n\n/* ======================= Sekante → Tangente ======================= */\nlabor({id:'tangente', fach:'Mathematik', titel:'Von der Sekante zur Tangente',\n  intro:'Die Sekante durch P(x₀ | f(x₀)) und Q(x₀ + h | f(x₀ + h)) hat die Steigung (f(x₀ + h) − f(x₀)) ÷ h. Mache h immer kleiner: Die Sekante wird zur Tangente, ihre Steigung zur <b>Ableitung f′(x₀)<\/b>.',\n  bau(L){\n    const F = [{t:'f(x) = 0,5x²', f:x => 0.5 * x * x, d:x => x}, {t:'f(x) = 0,25x³ − x', f:x => 0.25 * x * x * x - x, d:x => 0.75 * x * x - 1}, {t:'f(x) = e<sup>x<\/sup>', f:Math.exp, d:Math.exp}];\n    const H = [2, 1.5, 1, 0.5, 0.25, 0.1, 0.05, 0.01, 0.001];\n    const term = h('div', {class:'term'}), svg = neuesSvg(L.links), info = h('div', {class:'info'}), tab = h('div', {class:'scroll'});\n    L.links.prepend(term); L.links.append(info, tab);\n    const W = auswahl(L.rechts, 'Funktion', F.map(x => x.t.replace(/<[^>]+>/g, '')), () => { notiz = []; spur = []; zeichne(); });\n    const X0 = regler(L.rechts, {t:'Stelle x₀', min:-2, max:2, step:0.5, wert:1}, zeichne), Hh = regler(L.rechts, {t:'Abstand h', min:0, max:H.length - 1, step:1, wert:0, fmt:i => zf(H[i], 3)}, zeichne);\n    const ab = h('input', {type:'checkbox'}); L.rechts.append(h('label', {class:'feld'}, ab, h('span', {}, 'Ableitungsgraph mitzeichnen (bei h ≤ 0,01 Punkte sammeln)')));\n    ab.addEventListener('change', zeichne);\n    L.rechts.append(h('div', {class:'knoepfe'}, h('button', {class:'knopf', onclick:() => { const s = steig(); notiz.push({x0:X0.wert, h:H[Hh.wert], m:s}); zeichne(); }}, 'Steigung notieren')));\n    let notiz = [], spur = [];\n    const fn = () => F[W.wert], steig = () => { const x0 = X0.wert, hh = H[Hh.wert]; return (fn().f(x0 + hh) - fn().f(x0)) / hh; };\n    function zeichne(){\n      const f = fn().f, x0 = X0.wert, hh = H[Hh.wert], m = steig(), y0 = f(x0);\n      if (ab.checked && hh <= 0.01 && !spur.some(p => p.x === x0)) spur.push({x:x0, y:m});\n      term.innerHTML = fn().t;\n      plot(svg, {x0:-3, x1:3, y0:-4, y1:6, kurven:[{f}, {f:x => y0 + m * (x - x0), farbe:'var(--blau)', breite:1.8}],\n        punkte:[{x:x0, y:y0, farbe:'var(--tinte)', t:'P'}, {x:x0 + hh, y:f(x0 + hh), farbe:'var(--blau)', t:hh >= 0.25 ? 'Q' : ''}].concat(ab.checked ? spur.map(p => ({x:p.x, y:p.y, farbe:'var(--moos)', r:4})) : [])});\n      info.innerHTML = `Sekantensteigung = (f(${zf(x0)} + ${zf(hh, 3)}) − f(${zf(x0)})) ÷ ${zf(hh, 3)} = <b>${zf(m, 4)}<\/b>` + (hh <= 0.01 ? `<br>Das ist fast genau die Tangentensteigung f′(${zf(x0)}) = ${zf(fn().d(x0), 4)}.` : '') + (ab.checked ? `<br><span style=\"color:var(--moos)\">Grüne Punkte: (x₀ | Steigung) – so entsteht das Schaubild der Ableitung.<\/span>` : '');\n      tab.innerHTML = notiz.length ? '<table class=\"lab\"><tr><th>x₀<\/th><th>h<\/th><th>Sekantensteigung<\/th><\/tr>' + notiz.map(n => `<tr><td>${zf(n.x0)}<\/td><td>${zf(n.h, 3)}<\/td><td>${zf(n.m, 4)}<\/td><\/tr>`).join('') + '<\/table>' : '';\n      L.pruefen();\n    }\n    zeichne();\n    L.auftraege([\n      {t:'Notiere die Sekantensteigungen für <b>mindestens drei verschiedene h<\/b> an derselben Stelle x₀.', ok:() => notiz.some(n => new Set(notiz.filter(m => m.x0 === n.x0).map(m => m.h)).size >= 3)},\n      {t:'Mache h so klein (h ≤ 0,01), dass die Sekante praktisch die <b>Tangente bei x₀ = 1<\/b> ist.', ok:() => X0.wert === 1 && H[Hh.wert] <= 0.01},\n      {t:'Zeichne <b>mindestens fünf Punkte<\/b> des Ableitungsgraphen (Häkchen setzen, h ≤ 0,01, x₀ verschieben).', ok:() => ab.checked && spur.length >= 5}\n    ]);\n  }});\n\n/* ======================= Ober- und Untersumme ======================= */\nlabor({id:'flaeche', fach:'Mathematik', titel:'Fläche unter dem Schaubild: Ober- und Untersumme',\n  intro:'Die Fläche zwischen Schaubild und x-Achse wird durch Rechtecke angenähert. <span style=\"color:var(--blau)\">Untersumme<\/span>: Rechtecke unterhalb, <span style=\"color:var(--rot)\">Obersumme<\/span>: Rechtecke oberhalb. Je mehr Streifen, desto genauer.',\n  bau(L){\n    const F = [{t:'f(x) = 0,5x² + 1 auf [0; 3]', f:x => 0.5 * x * x + 1, a:0, b:3, I:7.5, steigt:true}, {t:'f(x) = 4 − x² auf [0; 2]', f:x => 4 - x * x, a:0, b:2, I:16 / 3, steigt:false}];\n    const term = h('div', {class:'term'}), svg = neuesSvg(L.links), info = h('div', {class:'info'});\n    L.links.prepend(term); L.links.append(info);\n    const W = auswahl(L.rechts, 'Funktion', F.map(x => x.t), zeichne), N = regler(L.rechts, {t:'Anzahl der Streifen n', min:1, max:50, step:1, wert:4}, zeichne);\n    let U = 0, O = 0;\n    function zeichne(){\n      const fn = F[W.wert], n = N.wert, d = (fn.b - fn.a) / n, fl = []; U = 0; O = 0;\n      for (let i = 0; i < n; i++){ const x1 = fn.a + i * d, x2 = x1 + d, l = fn.f(x1), r = fn.f(x2), lo = Math.min(l, r), hi = Math.max(l, r); U += lo * d; O += hi * d;\n        fl.push({pts:[[x1, 0], [x2, 0], [x2, hi], [x1, hi]], farbe:'var(--rot)', deckung:.12, rand:'var(--rot)'}, {pts:[[x1, 0], [x2, 0], [x2, lo], [x1, lo]], farbe:'var(--blau)', deckung:.3, rand:'var(--blau)'}); }\n      term.innerHTML = fn.t;\n      plot(svg, {x0:-0.3, x1:fn.b + 0.5, y0:-0.5, y1:6, xs:0.5, fx:v => zf(v, 1), flaechen:fl, kurven:[{f:fn.f}]});\n      info.innerHTML = `Streifenbreite ${zf(d, 3)}; <b style=\"color:var(--blau)\">Untersumme U = ${zf(U, 3)}<\/b>; <b style=\"color:var(--rot)\">Obersumme O = ${zf(O, 3)}<\/b>; Differenz O − U = ${zf(O - U, 3)}.<br>Exakter Flächeninhalt (Integral): ${zf(fn.I, 3)} – er liegt immer zwischen U und O.`;\n      L.pruefen();\n    }\n    zeichne();\n    L.auftraege([\n      {t:'Wähle n so, dass <b>O − U kleiner als 1<\/b> ist.', ok:() => O - U < 1},\n      {t:'Wähle n so, dass <b>O − U kleiner als 0,5<\/b> ist.', ok:() => O - U < 0.5},\n      {t:'Vergleiche: Bei welcher Funktion ist die Untersumme links, bei welcher rechts am Streifen? (Wechsle die Funktion.)', ok:() => W.wert === 1}\n    ]);\n  }});\n\n/* ======================= Gauß-Werkstatt ======================= */\nlabor({id:'gauss', fach:'Mathematik', titel:'Gauß-Werkstatt',\n  intro:'Forme das Gleichungssystem per Klick in Stufenform um. „Tipp“ trägt einen sinnvollen Schritt ein, „Ausführen“ zeigt die Rechnung Spalte für Spalte. Danach trägst du die Lösung ein.',\n  bau(L){\n    const halter = h('div'); L.links.append(halter);\n    const loes = h('div'); L.rechts.append(h('div', {class:'augenbraue'}, 'Lösung eintragen'), loes);\n    let S, M0;\n    const groesse = auswahl(L.rechts, 'Größe', ['2 Gleichungen, 2 Variablen', '3 Gleichungen, 3 Variablen'], neu);\n    L.rechts.prepend(h('div', {class:'knoepfe'}, h('button', {class:'knopf', onclick:neu}, 'Neues Gleichungssystem')));\n    const fb = h('div', {class:'info'}); L.rechts.append(fb);\n    let felder = [];\n    function neu(){\n      const n = groesse.wert ? 3 : 2;\n      for (let k = 0; k < 200; k++){ S = Array.from({length:n}, () => Math.floor(Math.random() * 9) - 4); const A = Array.from({length:n}, () => Array.from({length:n}, () => Math.floor(Math.random() * 7) - 3));\n        if (!A[0][0] || A.slice(1).some(z => !z[0]) || A.some(z => z.every(v => !v))) continue; const d = n === 2 ? A[0][0] * A[1][1] - A[0][1] * A[1][0] : A[0][0] * (A[1][1] * A[2][2] - A[1][2] * A[2][1]) - A[0][1] * (A[1][0] * A[2][2] - A[1][2] * A[2][0]) + A[0][2] * (A[1][0] * A[2][1] - A[1][1] * A[2][0]);\n        if (!d) continue; M0 = A.map(z => z.concat([z.reduce((s, v, j) => s + v * S[j], 0)])); break; }\n      halter.innerHTML = maWerkstatt(M0); loes.innerHTML = ''; fb.textContent = '';\n      felder = ['x', 'y', 'z'].slice(0, n).map(v => { const f = zahlFeld(loes, v + ' =', '', () => L.pruefen()); f.el.value = ''; return f; });\n      loes.append(h('div', {class:'knoepfe'}, h('button', {class:'knopf primaer', onclick:() => { const ok = felder.every((f, i) => f.el.value !== '' && nah(f.wert, S[i], 1e-9)); fb.className = 'info ' + (ok ? 'gut' : 'schlecht'); fb.textContent = ok ? 'Richtig gelöst!' : 'Noch nicht richtig – prüfe das Rückwärtseinsetzen.'; geloest = geloest || ok; L.pruefen(); }}, 'Lösung prüfen')));\n      L.pruefen();\n    }\n    let geloest = false;\n    halter.addEventListener('click', () => setTimeout(() => L.pruefen(), 0));\n    const M = () => { const w = halter.querySelector('.ma-ws'); return w ? JSON.parse(w.dataset.m) : null; };\n    neu();\n    L.auftraege([\n      {t:'Eliminiere in Zeile II die Variable x.', ok:() => M() && M()[1][0] === 0},\n      {t:'Bringe ein System mit <b>drei<\/b> Gleichungen auf <b>Stufenform<\/b>.', ok:() => { const m = M(); return m && m.length === 3 && m[1][0] === 0 && m[2][0] === 0 && m[2][1] === 0; }},\n      {t:'Trage die Lösung ein und lass sie prüfen.', ok:() => geloest}\n    ]);\n  }});\n/* ---------- Labor: Buchführung und KLR ---------- */\n\n/* ======================= T-Konto-Werkstatt ======================= */\nlabor({id:'tkonten', breit:true, fach:'Buchführung und KLR', titel:'T-Konto-Werkstatt: buchen und abschließen',\n  intro:'Buche die Geschäftsfälle (vereinfacht ohne Umsatzsteuer). Wähle Soll- und Habenkonto – richtige Buchungen wandern sichtbar auf die Konten. Danach schließt du die Konten ab: Erfolgskonten über die GuV, die GuV über das Eigenkapital, Bestandskonten über das SBK.',\n  bau(L){\n    const K = {\n      '0840':{n:'Fuhrpark', art:'A', ab:40000}, '0870':{n:'BGA', art:'A', ab:25000}, '2400':{n:'Forderungen a. LL', art:'A', ab:8000}, '2800':{n:'Bank', art:'A', ab:30000}, '2880':{n:'Kasse', art:'A', ab:2000},\n      '3000':{n:'Eigenkapital', art:'P', ab:70000}, '4250':{n:'Darlehen', art:'P', ab:25000}, '4400':{n:'Verbindlichkeiten a. LL', art:'P', ab:10000},\n      '5000':{n:'Umsatzerlöse', art:'E'}, '6000':{n:'Aufw. Rohstoffe', art:'AW'}, '6200':{n:'Löhne', art:'AW'}, '6700':{n:'Mieten', art:'AW'}};\n    const FAELLE = [\n      {t:'Einkauf von Rohstoffen auf Ziel', b:6000, s:'6000', h:'4400', tipp:'Rohstoffverbrauch ist Aufwand (aufwandsorientiert gebucht); die Schuld beim Lieferanten wächst.'},\n      {t:'Verkauf eigener Erzeugnisse auf Ziel', b:15000, s:'2400', h:'5000', tipp:'Es entsteht eine Forderung; der Umsatzerlös ist ein Ertrag (Ertrag im Haben).'},\n      {t:'Ein Kunde überweist eine offene Rechnung', b:8000, s:'2800', h:'2400', tipp:'Bankguthaben steigt (Soll), Forderung sinkt (Haben).'},\n      {t:'Banküberweisung der Löhne', b:4500, s:'6200', h:'2800', tipp:'Löhne sind Aufwand (Aufwand im Soll); das Bankguthaben sinkt.'},\n      {t:'Barzahlung der Miete für eine Lagerhalle', b:1200, s:'6700', h:'2880', tipp:'Miete ist Aufwand; die Kasse nimmt ab.'},\n      {t:'Wir begleichen eine Lieferantenrechnung per Banküberweisung', b:7000, s:'4400', h:'2800', tipp:'Die Verbindlichkeit sinkt (Passivkonto: Abnahme im Soll).'},\n      {t:'Kauf eines Lieferwagens gegen Banküberweisung', b:20000, s:'0840', h:'2800', tipp:'Aktivtausch: Fuhrpark nimmt zu, Bank nimmt ab.'},\n      {t:'Tilgung eines Darlehens per Bank', b:5000, s:'4250', h:'2800', tipp:'Die Darlehensschuld sinkt (Soll), die Bank nimmt ab (Haben).'},\n      {t:'Bareinzahlung auf das Bankkonto', b:1000, s:'2800', h:'2880', tipp:'Aktivtausch: Bank nimmt zu, Kasse nimmt ab.'}];\n    if (window.LABOR_VARIANTE === 'agentur'){   // Kommunikationsagentur: Fremdleistungen und Agenturerlöse\n      K['6000'].n = 'Aufwendungen für Fremdleistungen'; K['5000'].n = 'Umsatzerlöse';\n      Object.assign(FAELLE[0], {t:'Eingangsrechnung einer Druckerei für Flyer (Fremdleistung) auf Ziel', tipp:'Fremdleistungen sind Aufwand; die Schuld beim Lieferanten wächst.'});\n      Object.assign(FAELLE[1], {t:'Ausgangsrechnung an einen Kunden für eine Werbekampagne', tipp:'Es entsteht eine Forderung; der Umsatzerlös ist ein Ertrag (Ertrag im Haben).'});\n    }\n    if (window.LABOR_VARIANTE === 'handel'){   // Handelsbetrieb: Waren statt Rohstoffe und eigene Erzeugnisse\n      K['6000'].n = 'Aufwendungen für Waren'; K['5000'].n = 'Umsatzerlöse für Waren';\n      Object.assign(FAELLE[0], {t:'Einkauf von Waren auf Ziel', tipp:'Der Wareneinkauf wird als Aufwand gebucht; die Schuld beim Lieferanten wächst.'});\n      Object.assign(FAELLE[1], {t:'Verkauf von Waren auf Ziel', tipp:'Es entsteht eine Forderung; der Umsatzerlös ist ein Ertrag (Ertrag im Haben).'});\n    }\n    const ORD = ['0840', '0870', '2400', '2800', '2880', '3000', '4250', '4400', '5000', '6000', '6200', '6700'];\n    const B = {}; ORD.concat(['8020', '8010']).forEach(k => B[k] = {s:[], h:[], zu:false});\n    ORD.forEach(k => { const v = K[k]; if (v.ab){ (v.art === 'A' ? B[k].s : B[k].h).push({t:'AB', b:v.ab}); } });\n    let fall = 0, neuKey = '';\n    const kopf = h('div'), raster = h('div', {class:'tkonten'}), info = h('div', {class:'info'});\n    L.links.append(raster); L.rechts.append(kopf);\n    const opt = ORD.map(k => K[k].n);   // nur Kontennamen – passt zu jedem Kontenrahmen\n    const ss = auswahl(L.rechts, 'Soll', opt), hh = auswahl(L.rechts, 'Haben', opt);\n    const kn = h('div', {class:'knoepfe'}, h('button', {class:'knopf primaer', onclick:buchen}, 'Buchen'), h('button', {class:'knopf', onclick:() => { const F = FAELLE[fall]; if (F){ ss.setze(ORD.indexOf(F.s)); hh.setze(ORD.indexOf(F.h)); info.className = 'info'; info.innerHTML = 'Lösung eingetragen – mit „Buchen“ übernehmen.'; } }}, 'Lösung zeigen'));\n    L.rechts.append(kn, info, h('div', {class:'augenbraue', style:'margin-top:.8rem'}, 'Abschluss'), h('p', {class:'legende'}, 'Nach allen Buchungen: Knopf „abschließen“ im jeweiligen Konto. Reihenfolge: Erfolgskonten → GuV → Bestandskonten.'));\n    const summe = a => a.reduce((s, x) => s + x.b, 0);\n    function buchen(){\n      const F = FAELLE[fall]; if (!F) return;\n      const s = ORD[ss.wert], hb = ORD[hh.wert];\n      if (s === F.s && hb === F.h){ B[s].s.push({t:`(${fall + 1}) ${K[hb].n}`, b:F.b}); B[hb].h.push({t:`(${fall + 1}) ${K[s].n}`, b:F.b}); neuKey = fall + 1 + ''; fall++; info.className = 'info gut'; info.innerHTML = `Richtig: <b>${K[s].n} an ${K[hb].n} ${ze(F.b)}<\/b>`; }\n      else { info.className = 'info schlecht'; info.innerHTML = `Noch nicht richtig. Tipp: ${F.tipp}`; }\n      zeichne();\n    }\n    function abschluss(k){\n      const ziel = k === '8020' ? '3000' : K[k] && (K[k].art === 'E' || K[k].art === 'AW') ? '8020' : '8010';\n      if (fall < FAELLE.length){ info.className = 'info schlecht'; info.textContent = 'Erst alle Geschäftsfälle buchen.'; return; }\n      if (k === '8020' && ['5000', '6000', '6200', '6700'].some(e => !B[e].zu)){ info.className = 'info schlecht'; info.textContent = 'Zuerst alle Erfolgskonten über die GuV abschließen.'; return; }\n      if (k === '3000' && !B['8020'].zu){ info.className = 'info schlecht'; info.textContent = 'Das Eigenkapital erst abschließen, wenn der Gewinn aus der GuV übertragen ist.'; return; }\n      const S = summe(B[k].s), H = summe(B[k].h), sal = Math.abs(S - H);\n      if (S >= H){ B[k].h.push({t:{8010:'SBK', 8020:'GuV', 3000:'EK'}[ziel], b:sal, saldo:true}); B[ziel].s.push({t:k === '8020' ? 'Verlust' : K[k].n, b:sal}); }\n      else { B[k].s.push({t:{8010:'SBK', 8020:'GuV', 3000:'EK'}[ziel], b:sal, saldo:true}); B[ziel].h.push({t:k === '8020' ? 'Gewinn' : K[k].n, b:sal}); }\n      B[k].zu = true; neuKey = 'abschluss';\n      info.className = 'info gut'; info.innerHTML = k === '8020' ? `GuV abgeschlossen: ${S < H ? 'Gewinn' : 'Verlust'} von ${ze(sal)} geht ins Eigenkapital.` : `${K[k].n}: Saldo ${ze(sal)} auf die ${S >= H ? 'Habenseite' : 'Sollseite'} → Gegenbuchung im ${ziel === '8010' ? 'SBK' : ziel === '8020' ? 'GuV-Konto' : 'Eigenkapital'}.`;\n      if (ORD.every(x => B[x].zu)){ B['8010'].zu = true; }\n      zeichne();\n    }\n    function tk(k, name){\n      const S = B[k].s, H = B[k].h, zu = B[k].zu, sm = Math.max(summe(S), summe(H));\n      const zl = arr => arr.map(x => h('div', {class:'z' + (x.saldo ? ' saldo' : '') + (x.t.startsWith('(' + neuKey + ')') ? ' neu' : '')}, h('span', {}, x.t), h('span', {}, zf(x.b, 0)))).concat(zu ? [h('div', {class:'z summe'}, h('span', {}, ''), h('span', {}, zf(sm, 0)))] : []);\n      const kann = !zu && k !== '8010';\n      return h('div', {class:'tk' + (zu ? ' zu' : '')}, h('h4', {}, `S  ${name}  H`), h('div', {class:'seiten'}, h('div', {}, zl(S)), h('div', {}, zl(H))),\n        kann ? h('button', {class:'knopf', onclick:() => abschluss(k)}, 'abschließen') : null);\n    }\n    function zeichne(){\n      const F = FAELLE[fall];\n      kopf.innerHTML = F ? `<div class=\"augenbraue\">Geschäftsfall ${fall + 1} von ${FAELLE.length}<\/div><div class=\"term\">${F.t}: ${ze(F.b)}<\/div>` : '<div class=\"augenbraue\">Alle Geschäftsfälle gebucht<\/div><div class=\"term\">Jetzt die Konten abschließen.<\/div>';\n      raster.innerHTML = '';\n      ORD.forEach(k => raster.appendChild(tk(k, K[k].n)));\n      raster.appendChild(tk('8020', 'GuV')); raster.appendChild(tk('8010', 'SBK'));\n      L.pruefen();\n    }\n    zeichne();\n    const erfolg = ['5000', '6000', '6200', '6700'];\n    L.auftraege([\n      {t:'Buche die ersten <b>drei<\/b> Geschäftsfälle richtig.', ok:() => fall >= 3},\n      {t:'Buche <b>alle<\/b> Geschäftsfälle.', ok:() => fall >= FAELLE.length},\n      {t:'Schließe alle <b>Erfolgskonten<\/b> über das GuV-Konto ab.', ok:() => erfolg.every(e => B[e].zu)},\n      {t:'Schließe das <b>GuV-Konto<\/b> ab (Gewinn ins Eigenkapital).', ok:() => B['8020'].zu},\n      {t:'Schließe alle <b>Bestandskonten<\/b> ab – das SBK muss ausgeglichen sein.', ok:() => B['8010'].zu && summe(B['8010'].s) === summe(B['8010'].h)}\n    ]);\n  }});\n\n/* ======================= Break-even-Labor ======================= */\nlabor({id:'breakeven', fach:'Buchführung und KLR', titel:'Break-even-Labor: Gewinnschwelle',\n  intro:'Kosten K(x) = K<sub>f<\/sub> + k<sub>v<\/sub> · x und Erlöse E(x) = p · x. Wo sich beide Geraden schneiden, liegt die <b>Gewinnschwelle<\/b>. Verändere Preis, variable Stückkosten und Fixkosten.',\n  bau(L){\n    const svg = neuesSvg(L.links), info = h('div', {class:'info'}); L.links.append(info);\n    const P = regler(L.rechts, {t:'Verkaufspreis p je Stück', min:5, max:60, step:1, wert:30, fmt:v => ze(v)}, zeichne);\n    const KV = regler(L.rechts, {t:'variable Stückkosten k<sub>v<\/sub>', min:2, max:50, step:1, wert:18, fmt:v => ze(v)}, zeichne);\n    const KF = regler(L.rechts, {t:'Fixkosten K<sub>f<\/sub>', min:2000, max:30000, step:500, wert:9000, fmt:v => zeG(v)}, zeichne);\n    const X = regler(L.rechts, {t:'Absatzmenge x', min:0, max:2000, step:50, wert:600, fmt:v => zf(v, 0) + ' Stück'}, zeichne);\n    const g = x => (P.wert - KV.wert) * x - KF.wert;\n    function zeichne(){\n      const p = P.wert, kv = KV.wert, kf = KF.wert, x = X.wert, db = p - kv, bep = db > 0 ? kf / db : Infinity, ymax = Math.max(60000, p * 2000 * 0.6);\n      plot(svg, {x0:0, x1:2000, y0:0, y1:ymax, xs:250, ys:ymax > 60000 ? 20000 : 10000, fx:v => zf(v, 0), fy:v => zf(v / 1000, 0) + ' T', xt:'Menge x (Stück)', yt:'€',\n        kurven:[{f:t => kf + kv * t, farbe:'var(--rot)'}, {f:t => p * t, farbe:'var(--moos)'}, {f:() => kf, farbe:'var(--stumm)', breite:1.2, strich:'5 4'}],\n        linien:[{x1:x, y1:0, x2:x, y2:ymax, farbe:'var(--blau)', strich:'3 3'}],\n        punkte:Number.isFinite(bep) && bep <= 2000 ? [{x:bep, y:p * bep, farbe:'var(--tinte)', t:'Gewinnschwelle'}] : [],\n        texte:[{x:1980, y:Math.min(p * 1980, ymax * 0.95), t:'Erlöse', farbe:'var(--moos)', anker:'end'}, {x:1980, y:Math.min(kf + kv * 1980, ymax * 0.95) - ymax * 0.04, t:'Kosten', farbe:'var(--rot)', anker:'end'}]});\n      info.className = 'info' + (g(x) >= 0 ? ' gut' : ' schlecht');\n      info.innerHTML = `Deckungsbeitrag je Stück: ${ze(p)} − ${ze(kv)} = <b>${ze(db)}<\/b>; ` + (db > 0 ? `Gewinnschwelle: ${zeG(kf)} ÷ ${ze(db)} = <b>${zf(bep, 1)} Stück<\/b>.` : 'kein positiver Deckungsbeitrag – es gibt keine Gewinnschwelle!') +\n        `<br>Bei ${zf(x, 0)} Stück: Erlös ${zeG(p * x)}, Kosten ${zeG(kf + kv * x)} → <b>${g(x) >= 0 ? 'Gewinn' : 'Verlust'} ${zeG(Math.abs(g(x)))}<\/b>.`;\n      L.pruefen();\n    }\n    zeichne();\n    L.auftraege([\n      {t:'Stelle die Werte so ein, dass die <b>Gewinnschwelle bei genau 500 Stück<\/b> liegt.', ok:() => P.wert > KV.wert && nah(KF.wert / (P.wert - KV.wert), 500)},\n      {t:'Erreiche bei <b>1.000 Stück<\/b> einen Gewinn von mindestens <b>10.000 €<\/b> (Menge auf 1.000 stellen).', ok:() => X.wert === 1000 && g(1000) >= 10000},\n      {t:'Setze den Preis auf die <b>kurzfristige Preisuntergrenze<\/b> (Deckungsbeitrag 0).', ok:() => P.wert === KV.wert},\n      {t:'Verdopple die Fixkosten gegenüber dem Start (18.000 €) und beobachte: Die Gewinnschwelle verdoppelt sich.', ok:() => KF.wert === 18000}\n    ]);\n  }});\n\n/* ======================= Kalkulationsschema ======================= */\nlabor({id:'kalkulation', fach:'Buchführung und KLR', titel:'Kalkulationsschema zum Durchspielen (Handelskalkulation)',\n  intro:'Verändere Rabatte, Skonti und Zuschläge und verfolge, wie sich jede Änderung durch das Schema bis zum Preis fortpflanzt. Geänderte Zeilen leuchten kurz auf. Umschalten zwischen <b>Vorwärts<\/b>- und <b>Rückwärtskalkulation<\/b>.',\n  bau(L){\n    const tab = h('div', {class:'scroll'}), kenn = h('div', {class:'info'}); L.links.append(tab, kenn);\n    const modus = auswahl(L.rechts, 'Richtung', ['Vorwärts: vom Listeneinkaufspreis', 'Rückwärts: vom Listenverkaufspreis'], zeichne);\n    const start = zahlFeld(L.rechts, 'Ausgangspreis (€)', 100, zeichne, {step:1, min:1});\n    const R = {rab:regler(L.rechts, {t:'Liefererrabatt', min:0, max:30, step:1, wert:20, fmt:v => v + ' %'}, zeichne), sko:regler(L.rechts, {t:'Liefererskonto', min:0, max:3, step:0.5, wert:2, fmt:v => zf(v) + ' %'}, zeichne),\n      bzk:regler(L.rechts, {t:'Bezugskosten je Stück', min:0, max:20, step:0.5, wert:5, fmt:v => ze(v)}, zeichne), hk:regler(L.rechts, {t:'Handlungskostenzuschlag', min:0, max:60, step:1, wert:25, fmt:v => v + ' %'}, zeichne),\n      gew:regler(L.rechts, {t:'Gewinnzuschlag', min:0, max:40, step:1, wert:15, fmt:v => v + ' %'}, zeichne), ksk:regler(L.rechts, {t:'Kundenskonto (im Hundert)', min:0, max:3, step:0.5, wert:2, fmt:v => zf(v) + ' %'}, zeichne),\n      kra:regler(L.rechts, {t:'Kundenrabatt (im Hundert)', min:0, max:30, step:1, wert:10, fmt:v => v + ' %'}, zeichne)};\n    let alt = {}, Z = {};\n    function rechne(){\n      const r = k => R[k].wert / 100, v = {};\n      if (modus.wert === 0){ v.lep = start.wert; v.rab = v.lep * r('rab'); v.zep = v.lep - v.rab; v.sko = v.zep * r('sko'); v.bep = v.zep - v.sko; v.bzk = R.bzk.wert; v.bzp = v.bep + v.bzk;\n        v.hk = v.bzp * r('hk'); v.sk = v.bzp + v.hk; v.gew = v.sk * r('gew'); v.bvp = v.sk + v.gew; v.zvp = v.bvp / (1 - r('ksk')); v.ksk = v.zvp - v.bvp; v.lvp = v.zvp / (1 - r('kra')); v.kra = v.lvp - v.zvp; }\n      else { v.lvp = start.wert; v.kra = v.lvp * r('kra'); v.zvp = v.lvp - v.kra; v.ksk = v.zvp * r('ksk'); v.bvp = v.zvp - v.ksk; v.sk = v.bvp / (1 + r('gew')); v.gew = v.bvp - v.sk; v.bzp = v.sk / (1 + r('hk')); v.hk = v.sk - v.bzp;\n        v.bzk = R.bzk.wert; v.bep = v.bzp - v.bzk; v.zep = v.bep / (1 - r('sko')); v.sko = v.zep - v.bep; v.lep = v.zep / (1 - r('rab')); v.rab = v.lep - v.zep; }\n      return v;\n    }\n    function zeichne(){\n      const v = rechne(), rueck = modus.wert === 1;\n      const Zl = [['lep', 'Listeneinkaufspreis'], ['rab', '− Liefererrabatt', R.rab.wert + ' %'], ['zep', '= Zieleinkaufspreis', '', 1], ['sko', '− Liefererskonto', zf(R.sko.wert) + ' %'], ['bep', '= Bareinkaufspreis', '', 1], ['bzk', '+ Bezugskosten'], ['bzp', '= Bezugspreis', '', 1],\n        ['hk', '+ Handlungskosten', R.hk.wert + ' %'], ['sk', '= Selbstkosten', '', 1], ['gew', '+ Gewinn', R.gew.wert + ' %'], ['bvp', '= Barverkaufspreis', '', 1], ['ksk', '+ Kundenskonto', zf(R.ksk.wert) + ' % i. H.'], ['zvp', '= Zielverkaufspreis', '', 1], ['kra', '+ Kundenrabatt', R.kra.wert + ' % i. H.'], ['lvp', '= Listenverkaufspreis', '', 1]];\n      tab.innerHTML = `<div class=\"augenbraue\">${rueck ? 'Rückwärtskalkulation: von unten nach oben rechnen' : 'Vorwärtskalkulation: von oben nach unten rechnen'}<\/div><table class=\"lab\"><tr><th>Schema<\/th><th>Satz<\/th><th>€<\/th><\/tr>` +\n        Zl.map(([k, t, s, sum]) => `<tr class=\"${sum ? 'summe' : ''}${alt[k] != null && Math.abs(alt[k] - v[k]) > 0.004 ? ' neu' : ''}\"><td>${t}<\/td><td>${s || ''}<\/td><td>${ze(v[k])}<\/td><\/tr>`).join('') + '<\/table>';\n      alt = v; Z = v;\n      const kz = (v.lvp - v.bzp) / v.bzp * 100, hs = (v.lvp - v.bzp) / v.lvp * 100, kf = v.lvp / v.bzp;\n      kenn.innerHTML = `Kalkulationszuschlag ${zf(kz)} %; Kalkulationsfaktor ${zf(kf, 4)}; Handelsspanne ${zf(hs)} %` + (rueck ? `<br>Höchstens zahlbarer Listeneinkaufspreis: <b>${ze(v.lep)}<\/b>` : `<br>Listenverkaufspreis: <b>${ze(v.lvp)}<\/b>`);\n      L.pruefen();\n    }\n    zeichne();\n    L.auftraege([\n      {t:'Wie ändert sich der Listenverkaufspreis, wenn du den <b>Kundenrabatt auf 20 %<\/b> erhöhst? (Vorwärts)', ok:() => modus.wert === 0 && R.kra.wert === 20},\n      {t:'Erreiche einen <b>Kalkulationsfaktor unter 1,5<\/b> (Vorwärts).', ok:() => modus.wert === 0 && Z.lvp / Z.bzp < 1.5},\n      {t:'Rückwärtskalkulation: Welcher Listeneinkaufspreis ist bei einem <b>Listenverkaufspreis von 199 €<\/b> höchstens möglich?', ok:() => modus.wert === 1 && start.wert === 199},\n      {t:'Rückwärts: Stelle die Zuschläge so ein, dass der Lieferant <b>mindestens 140 €<\/b> Listeneinkaufspreis verlangen darf (LVP 199 €).', ok:() => modus.wert === 1 && start.wert === 199 && Z.lep >= 140}\n    ]);\n  }});\n\n/* ======================= BAB-Werkstatt ======================= */\nlabor({id:'bab', breit:true, fach:'Buchführung und KLR', titel:'BAB-Werkstatt: Gemeinkosten verteilen',\n  intro:'Der Betriebsabrechnungsbogen verteilt die Gemeinkosten auf die Kostenstellen. Arbeite die Schritte nacheinander ab. Danach kannst du den Umlageschlüssel der allgemeinen Hilfskostenstelle ändern und die Wirkung auf die Zuschlagssätze beobachten.',\n  bau(L){\n    const KS = ['Allg. Hilfskostenstelle', 'Material', 'Fertigung', 'Verwaltung', 'Vertrieb'];\n    const GK = [{n:'Hilfs- und Betriebsstoffe', b:24000, s:[2000, 4000, 15000, 1000, 2000], sl:'lt. Entnahmescheinen (siehe Belege)'}, {n:'Gehälter', b:60000, s:[1, 2, 3, 4, 2], sl:'1 : 2 : 3 : 4 : 2'},\n      {n:'Abschreibungen', b:36000, s:[2, 2, 6, 1, 1], sl:'2 : 2 : 6 : 1 : 1'}, {n:'Sonstige Gemeinkosten', b:18000, s:[100, 200, 400, 100, 100], sl:'m²: 100 : 200 : 400 : 100 : 100'}];\n    const EK = {fm:120000, fl:80000};\n    let schritt = 0, verteilt = 0;\n    const tab = h('div', {class:'scroll'}), info = h('div', {class:'info'});\n    const belege = h('details', {style:'margin:.4rem 0 .6rem'}, h('summary', {style:'cursor:pointer;font-weight:600'}, 'Belege: Materialentnahmescheine für Hilfs- und Betriebsstoffe'),\n      h('p', {class:'legende', html:'Hilfs- und Betriebsstoffe werden nicht über einen Schlüssel verteilt: Jede Entnahme aus dem Lager wird auf einem <b>Materialentnahmeschein<\/b> mit der empfangenden Kostenstelle erfasst. Die Summen je Kostenstelle werden direkt übernommen.'}),\n      h('div', {class:'scroll', html:'<table class=\"lab\"><tr><th>Entnahmescheine Nr.<\/th><th>Kostenstelle<\/th><th>Betrag<\/th><\/tr>' + KS.map((k, j) => `<tr><td>${['E-101 bis E-104', 'E-105 bis E-112', 'E-113 bis E-140', 'E-141', 'E-142 bis E-145'][j]}<\/td><td>${k}<\/td><td>${zf(GK[0].s[j], 0)} €<\/td><\/tr>`).join('') + '<tr class=\"summe\"><td>Summe<\/td><td><\/td><td>24.000 €<\/td><\/tr><\/table>'}));\n    L.links.append(belege, info, tab);\n    const kn = h('div', {class:'knoepfe'}); L.rechts.append(kn);\n    L.rechts.append(h('div', {class:'augenbraue', style:'margin-top:.8rem'}, 'Umlageschlüssel der allg. Hilfskostenstelle'));\n    const ugrid = h('div', {class:'umlage-grid'}); L.rechts.append(ugrid,\n      h('p', {class:'legende', html:'Umlageschlüssel für die 5 Kostenstellen. Nach „Summen bilden“ wird die allg. Hilfskostenstelle automatisch aus der Umlage herausgenommen (–): Ihr Betrag aus der Summenzeile wird auf die 4 Hauptkostenstellen verteilt.'}));\n    const um = [];\n    let allgEin;\n    KS.forEach((k, j) => { const inp = j ? h('input', {type:'number', value:[0, 1, 3, 1, 0][j], min:0, step:1, 'aria-label':'Umlage auf ' + k}) : h('input', {type:'text', value:'', placeholder:'?', 'aria-label':'Umlage auf ' + k, title:'Welcher Schlüssel gilt für die allg. Hilfskostenstelle selbst?'});\n      if (j){ inp.addEventListener('input', () => zeichne()); um.push({get wert(){ return +inp.value; }, el:inp}); } else { allgEin = inp; inp.addEventListener('input', () => { inp.classList.remove('falsch'); zeichne(); }); }\n      ugrid.append(h('label', {}, h('span', {}, k.replace('Allg. Hilfskostenstelle', 'Allg. Hilfs-KSt')), inp)); });\n    const SCHRITTE = [\n      {t:'Kostenart jetzt verteilen', fertig:() => verteilt === GK.length, dran:() => verteilt < GK.length, tu:() => { verteilt++; if (verteilt === GK.length) schritt = 1; }},\n      {t:'Alle Kostenarten verteilen', fertig:() => verteilt === GK.length, dran:() => verteilt < GK.length, tu:() => { verteilt = GK.length; schritt = 1; }},\n      {t:'Summen bilden', fertig:() => schritt >= 2, dran:() => schritt === 1, tu:() => { schritt = 2; }},\n      {t:'Allg. Hilfskostenstelle umlegen', fertig:() => schritt >= 3, dran:() => schritt === 2, tu:() => { const a = allgEin.value.trim();\n        if (!/^[-–−]$|^0$/.test(a)){ allgEin.classList.add('falsch'); info.className = 'info schlecht'; info.innerHTML = a === '' ? 'Trage zuerst auch für die <b>allg. Hilfskostenstelle<\/b> einen Umlageschlüssel ein.' : `Bei der allg. Hilfskostenstelle steht „${a}“ – sie kann sich aber nichts <b>selbst<\/b> umlegen, ihre Kosten werden ja gerade vollständig verteilt. Trage dort „–“ ein.`; return false; }\n        schritt = 3; }},\n      {t:'Zuschlagssätze berechnen', fertig:() => schritt >= 4, dran:() => schritt === 3, tu:() => { schritt = 4; }}];\n    SCHRITTE.forEach(S => { S.el = h('button', {class:'knopf', onclick:() => { if (S.dran()){ if (S.tu() === false){ knopfStand(); return; } zeichne(); } }}, S.t); kn.append(S.el); });\n    kn.append(h('button', {class:'knopf', onclick:() => { schritt = 0; verteilt = 0; zeichne(); }}, '↺ Neu starten'));\n    const knopfStand = () => SCHRITTE.forEach(S => { const f = S.fertig(), d = S.dran(); S.el.className = 'knopf' + (d ? ' primaer' : f ? ' getan' : ''); S.el.disabled = !d;\n      S.el.textContent = (f ? '✓ ' : '') + S.t; });\n    let Z = {};\n    function zeichne(){\n      const V = GK.map(g => { const sm = g.s.reduce((a, b) => a + b, 0); return g.sl.startsWith('lt. Entnahme') ? g.s.slice() : g.s.map(x => g.b * x / sm); });\n      const sum = KS.map((_, j) => V.reduce((a, r) => a + r[j], 0)), u = um.map(f => Math.max(0, f.wert)), us = u.reduce((a, b) => a + b, 0) || 1;\n      const uml = u.map(x => sum[0] * x / us), nach = [0, sum[1] + uml[0], sum[2] + uml[1], sum[3] + uml[2], sum[4] + uml[3]];\n      const hk = EK.fm + nach[1] + EK.fl + nach[2];\n      Z = {mgk:nach[1] / EK.fm * 100, fgk:nach[2] / EK.fl * 100, vwgk:nach[3] / hk * 100, vtgk:nach[4] / hk * 100};\n      const td = (v, neu) => `<td${neu ? ' style=\"background:var(--gold-bg)\"' : ''}>${v == null ? '' : zf(v, 0)}<\/td>`;\n      let s = `<table class=\"lab\"><tr><th>Gemeinkostenart<\/th><th>Betrag<\/th><th>Schlüssel<\/th>${KS.map(k => `<th>${k}<\/th>`).join('')}<\/tr>`;\n      GK.forEach((g, i) => s += `<tr><td>${g.n}<\/td><td>${zf(g.b, 0)}<\/td><td style=\"text-align:left\">${g.sl}<\/td>${KS.map((_, j) => i < verteilt ? td(V[i][j], i === verteilt - 1 && schritt === 0) : '<td><\/td>').join('')}<\/tr>`);\n      s += `<tr class=\"summe\"><td>Summe Gemeinkosten<\/td><td>${zf(138000, 0)}<\/td><td><\/td>${KS.map((_, j) => schritt >= 2 ? td(sum[j], schritt === 2) : '<td><\/td>').join('')}<\/tr>`;\n      s += `<tr><td>Umlage allg. Hilfskostenstelle<\/td><td><\/td><td style=\"text-align:left\">${u.join(' : ')}<br><span class=\"legende\">(oben eingestellt)<\/span><\/td>${schritt >= 3 ? `<td>−${zf(sum[0], 0)}<\/td>` + uml.map(x => td(x, schritt === 3)).join('') : '<td><\/td>'.repeat(5)}<\/tr>`;\n      s += `<tr class=\"summe\"><td>Gemeinkosten nach Umlage<\/td><td><\/td><td><\/td><td>${schritt >= 3 ? '–' : ''}<\/td>${[1, 2, 3, 4].map(j => schritt >= 3 ? td(nach[j], schritt === 3) : '<td><\/td>').join('')}<\/tr>`;\n      s += `<tr><td>Zuschlagsgrundlage<\/td><td><\/td><td><\/td><td><\/td><td>FM ${zf(EK.fm, 0)}<\/td><td>FL ${zf(EK.fl, 0)}<\/td>${schritt >= 3 ? `<td>HK ${zf(hk, 0)}<\/td><td>HK ${zf(hk, 0)}<\/td>` : '<td>HK ?<\/td><td>HK ?<\/td>'}<\/tr>`;\n      s += `<tr class=\"summe\"><td>Zuschlagssatz<\/td><td><\/td><td><\/td><td><\/td>${schritt >= 4 ? [Z.mgk, Z.fgk, Z.vwgk, Z.vtgk].map(x => `<td style=\"background:var(--moos-bg)\">${zf(x)} %<\/td>`).join('') : '<td><\/td>'.repeat(4)}<\/tr><\/table>`;\n      tab.innerHTML = s; knopfStand();\n      if (schritt >= 2){ allgEin.value = '–'; allgEin.disabled = true; allgEin.classList.remove('falsch'); } else if (allgEin.disabled){ allgEin.value = ''; allgEin.disabled = false; }\n      info.className = schritt === 4 ? 'info gut' : 'info';\n      info.innerHTML = ['Schritt 1: Verteile die Gemeinkostenarten nach ihren Schlüsseln (Betrag ÷ Summe der Schlüsselzahlen × Schlüsselzahl).', 'Schritt 2: Bilde je Kostenstelle die Summe.', 'Die allg. Hilfskostenstelle ist jetzt aus der Umlage herausgenommen (–). Schritt 3: Lege sie auf die 4 Hauptkostenstellen um (Schlüssel ' + u.join(' : ') + '). Ihr Betrag aus der Summenzeile wird vollständig verteilt, danach steht bei ihr „–“.', 'Schritt 4: Berechne die Zuschlagssätze: MGK auf Fertigungsmaterial, FGK auf Fertigungslöhne, VwGK und VtGK auf die Herstellkosten.', `✓ Fertig! MGK-Zuschlag ${zf(Z.mgk)} %, FGK-Zuschlag ${zf(Z.fgk)} %, VwGK-Zuschlag ${zf(Z.vwgk)} %, VtGK-Zuschlag ${zf(Z.vtgk)} %. <br><b>Ändere jetzt den Umlageschlüssel und beobachte die Zuschläge.<\/b>`][schritt] +\n        (schritt === 0 ? ` (${verteilt} von ${GK.length} verteilt)` + (verteilt ? '<br>' + (() => { const g = GK[verteilt - 1], sm = g.s.reduce((a, b) => a + b, 0);\n          return g.sl.startsWith('lt. Entnahme') ? `${g.n}: Beträge direkt von den Materialentnahmescheinen übernommen (siehe Belege).` : `${g.n}: ${zf(g.b, 0)} € ÷ ${zf(sm, 0)} Teile = ${zf(g.b / sm)} € je Teil; dann mit der Schlüsselzahl jeder Kostenstelle malnehmen.`; })() : '') : '');\n      L.pruefen();\n    }\n    zeichne();\n    L.auftraege([\n      {t:'Verteile <b>alle Gemeinkostenarten<\/b> auf die Kostenstellen.', ok:() => verteilt === GK.length},\n      {t:'Lege die <b>allgemeine Hilfskostenstelle<\/b> um.', ok:() => schritt >= 3},\n      {t:'Berechne die <b>Zuschlagssätze<\/b>.', ok:() => schritt >= 4},\n      {t:'Ändere den Umlageschlüssel so, dass der <b>Fertigungsgemeinkostenzuschlag über 85 %<\/b> liegt.', ok:() => schritt >= 4 && Z.fgk > 85}\n    ]);\n  }});\n/* ---------- Labor: BWL, Investition und Finanzierung ---------- */\n\n/* ======================= Netzplan-Werkstatt ======================= */\nlabor({id:'netzplan', breit:true, fach:'BWL, Investition und Finanzierung', titel:'Netzplan-Werkstatt: Schritt für Schritt',\n  intro:'Rechne den Netzplan Knoten für Knoten: zuerst <b>vorwärts<\/b> (FAZ, FEZ), dann <b>rückwärts<\/b> (SEZ, SAZ), dann die <b>Puffer<\/b>. Am Ende leuchtet der kritische Pfad. Danach kannst du einen Vorgang verzögern und sehen, ob sich das Projektende verschiebt.',\n  bau(L){\n    const V = [{nr:1, n:'Planung', d:3, vor:[], x:0, y:1}, {nr:2, n:'Material bestellen', d:5, vor:[0], x:1, y:0}, {nr:3, n:'Bauteile fertigen', d:4, vor:[0], x:1, y:2},\n      {nr:4, n:'Montage', d:6, vor:[1, 2], x:2, y:1}, {nr:5, n:'Dokumentation', d:3, vor:[2], x:2, y:3}, {nr:6, n:'Prüfung', d:2, vor:[3], x:3, y:1}, {nr:7, n:'Auslieferung', d:1, vor:[4, 5], x:4, y:2}];\n    const nach = V.map((_, i) => V.map((w, j) => w.vor.includes(i) ? j : -1).filter(j => j >= 0));\n    let phase = 0, idx = 0, letzter = null;   // 0 vorwärts, 1 rückwärts, 2 puffer, 3 fertig\n    const C = V.map(() => ({}));\n    const KEYS = [['faz', 'fez'], ['sez', 'saz'], ['gp', 'fp']]   // Reihenfolge = Eingabereihenfolge (Enter springt weiter)\n    let fokus = false, NAMEN = {faz:'FAZ', fez:'FEZ', saz:'SAZ', sez:'SEZ', gp:'GP', fp:'FP'};\n    const feld = h('div', {style:'position:relative;width:800px;height:430px;margin:0 auto'}), info = h('div', {class:'info'});\n    const legende = h('div', {class:'np-legende'},\n      h('div', {class:'np-k', style:'width:190px'}, h('div', {class:'r'}, h('div', {}, 'FAZ'), h('div', {}), h('div', {}, 'FEZ')), h('div', {class:'r'}, h('div', {}, 'Nr.'), h('div', {class:'name'}, 'Vorgang')),\n        h('div', {class:'r'}, h('div', {}, 'Dauer'), h('div', {}, 'GP'), h('div', {}, 'FP')), h('div', {class:'r'}, h('div', {}, 'SAZ'), h('div', {}), h('div', {}, 'SEZ'))),\n      h('div', {class:'legende', html:'<b>FAZ<\/b> frühester Anfangszeitpunkt · <b>FEZ<\/b> frühester Endzeitpunkt = FAZ + Dauer<br><b>SEZ<\/b> spätester Endzeitpunkt · <b>SAZ<\/b> spätester Anfangszeitpunkt = SEZ − Dauer<br><b>GP<\/b> Gesamtpuffer = SAZ − FAZ · <b>FP<\/b> freier Puffer = kleinster FAZ der Nachfolger − FEZ<br>Vorwärts: FAZ = größter FEZ der Vorgänger. Rückwärts: SEZ = kleinster SAZ der Nachfolger.'.replace(/ · /g, '; ')}));\n    L.links.append(legende, info, h('div', {class:'scroll'}, feld));\n    const kn = h('div', {class:'knoepfe'}); L.rechts.append(h('p', {class:'legende', html:'Trage im <b>gelb markierten Knoten<\/b> die beiden fehlenden Werte ein. Sobald beide stimmen, geht es <b>automatisch<\/b> im nächsten Knoten weiter. <b>Enter<\/b> springt zum zweiten Feld; „Prüfen“ zeigt, welcher Wert noch falsch ist. Mit „Lösung zeigen“ rechnet die Werkstatt den Knoten vor.'}), kn);\n    const bP = h('button', {class:'knopf primaer', onclick:() => { fokus = true; pruefe(); }}, 'Prüfen'), bN = h('button', {class:'knopf', onclick:() => schrittWeiter()}, 'Lösung zeigen'),\n      bA = h('button', {class:'knopf', onclick:() => { while (phase < 3) schrittWeiter(true); zeichne(); }}, 'Alles berechnen'),\n      bR = h('button', {class:'knopf', onclick:() => { phase = 0; idx = 0; endePlan = null; letzter = null; C.forEach(c => { for (const k in c) delete c[k]; }); verz.setze(0); zeichne(); info.className = 'info'; info.innerHTML = 'Neu gestartet – beginne mit Vorgang 1.'; }}, '↺ Neu starten');\n    kn.append(bP, bN, bA, bR);\n    L.rechts.append(h('div', {class:'augenbraue', style:'margin-top:.8rem'}, 'Was wäre, wenn …'));\n    const wahlV = auswahl(L.rechts, 'Vorgang verzögern', V.map(v => v.nr + ' ' + v.n), () => { if (phase >= 3) alles(); zeichne(); });\n    const verz = regler(L.rechts, {t:'Verzögerung (Tage)', min:0, max:6, step:1, wert:0}, () => { if (phase >= 3) alles(); zeichne(); });\n    L.rechts.append(h('p', {class:'legende'}, 'Verzögern geht, sobald der Netzplan fertig berechnet ist.'));\n    const dauer = i => V[i].d + (wahlV.wert === i ? verz.wert : 0);\n    let endePlan = null;\n    const ende = () => Math.max(...V.map((_, i) => C[i].fez));\n    function soll(i){   // Sollwerte des Knotens i in der aktuellen Phase\n      if (phase === 0){ const faz = Math.max(0, ...V[i].vor.map(j => C[j].fez)); return {faz, fez:faz + dauer(i)}; }\n      if (phase === 1){ const sez = nach[i].length ? Math.min(...nach[i].map(j => C[j].saz)) : ende(); return {sez, saz:sez - dauer(i)}; }\n      return {gp:C[i].saz - C[i].faz, fp:(nach[i].length ? Math.min(...nach[i].map(j => C[j].faz)) : ende()) - C[i].fez};\n    }\n    function erklaere(i){ const v = V[i], w = soll(i);\n      if (phase === 0) return `Vorgang ${v.nr}: FAZ = ${v.vor.length ? 'größter FEZ der Vorgänger (' + v.vor.map(j => V[j].nr + ': ' + C[j].fez).join(', ') + ')' : 'Projektstart'} = <b>${w.faz}<\/b>; FEZ = FAZ + Dauer = ${w.faz} + ${dauer(i)} = <b>${w.fez}<\/b>.`;\n      if (phase === 1) return `Vorgang ${v.nr}: SEZ = ${nach[i].length ? 'kleinster SAZ der Nachfolger (' + nach[i].map(j => V[j].nr + ': ' + C[j].saz).join(', ') + ')' : 'Projektende'} = <b>${w.sez}<\/b>; SAZ = SEZ − Dauer = ${w.sez} − ${dauer(i)} = <b>${w.saz}<\/b>.`;\n      return `Vorgang ${v.nr}: GP = SAZ − FAZ = ${C[i].saz} − ${C[i].faz} = <b>${w.gp}<\/b>; FP = ${nach[i].length ? 'kleinster FAZ der Nachfolger (' + nach[i].map(j => V[j].nr + ': ' + C[j].faz).join(', ') + ')' : 'Projektende ' + ende()} − FEZ ${C[i].fez} = <b>${w.fp}<\/b>.`;\n    }\n    function alles(){ V.forEach((v, i) => { C[i].faz = Math.max(0, ...v.vor.map(j => C[j].fez)); C[i].fez = C[i].faz + dauer(i); });\n      const e = ende(); for (let i = V.length - 1; i >= 0; i--){ C[i].sez = nach[i].length ? Math.min(...nach[i].map(j => C[j].saz)) : e; C[i].saz = C[i].sez - dauer(i); }\n      V.forEach((v, i) => { C[i].gp = C[i].saz - C[i].faz; C[i].fp = (nach[i].length ? Math.min(...nach[i].map(j => C[j].faz)) : e) - C[i].fez; }); }\n    function schrittWeiter(still, lob){\n      if (phase === 3) return;\n      const i = idx, txt = erklaere(i); Object.assign(C[i], soll(i)); letzter = i;\n      info.className = 'info' + (lob ? ' gut' : ''); info.innerHTML = (lob ? '✓ Richtig! ' : '') + txt;\n      if (phase === 0){ if (++idx === V.length){ phase = 1; idx = V.length - 1; if (endePlan == null) endePlan = ende(); info.innerHTML += '<br>Vorwärtsrechnung fertig – jetzt <b>rückwärts<\/b>, beginnend beim letzten Vorgang.'; } }\n      else if (phase === 1){ if (--idx < 0){ phase = 2; idx = 0; info.innerHTML += '<br>Rückwärtsrechnung fertig – jetzt die <b>Puffer<\/b>, beginnend bei Vorgang 1.'; } }\n      else if (++idx === V.length){ phase = 3; letzter = null; }\n      if (!still) zeichne();\n    }\n    function pruefe(){\n      if (phase === 3) return;\n      const w = soll(idx), ein = KEYS[phase].map(k => feld.querySelector(`input[data-k=\"${k}\"]`)), leer = ein.some(e => !e || e.value === '');\n      if (leer){ info.className = 'info schlecht'; info.textContent = 'Trage beide Werte im gelben Knoten ein.'; return; }\n      const falsch = KEYS[phase].filter((k, n) => +ein[n].value !== w[k]);\n      if (!falsch.length){ schrittWeiter(false, true); return; }\n      info.className = 'info schlecht';\n      info.innerHTML = 'Noch nicht richtig: ' + falsch.map(k => NAMEN[k]).join(' und ') + '. Tipp: ' + ['FAZ = größter FEZ aller Vorgänger (beim Start 0); FEZ = FAZ + Dauer.', 'SEZ = kleinster SAZ aller Nachfolger (beim letzten Vorgang: Projektende); SAZ = SEZ − Dauer.', 'GP = SAZ − FAZ; FP = kleinster FAZ der Nachfolger − eigener FEZ.'][phase];\n      falsch.forEach(k => feld.querySelector(`input[data-k=\"${k}\"]`).classList.add('falsch'));\n      const f1 = feld.querySelector(`input[data-k=\"${falsch[0]}\"]`); f1.focus({preventScroll:true}); f1.select();\n    }\n    feld.addEventListener('input', e => {   // automatisch weiter, sobald beide Werte stimmen (Fehler zeigt erst „Prüfen“ bzw. Enter)\n      if (!e.target.matches('input.np-ein') || phase === 3) return; e.target.classList.remove('falsch');\n      const w = soll(idx), ein = KEYS[phase].map(k => feld.querySelector(`input[data-k=\"${k}\"]`));\n      if (ein.every(x => x && x.value !== '') && KEYS[phase].every((k, n) => +ein[n].value === w[k])) { fokus = true; schrittWeiter(false, true); }\n    });\n    feld.addEventListener('keydown', e => { if (e.key !== 'Enter' || !e.target.matches('input.np-ein')) return; e.preventDefault(); fokus = true;\n      const ks = KEYS[phase], n = ks.indexOf(e.target.dataset.k), naechstes = feld.querySelector(`input[data-k=\"${ks[n + 1]}\"]`);\n      if (naechstes && naechstes.value === '') naechstes.focus({preventScroll:true}); else pruefe(); });\n    function zeichne(){\n      const BW = 140, BH = 88, GX = 165, GY = 100;\n      const pos = V.map(v => ({x:10 + v.x * GX, y:10 + v.y * GY}));\n      let pfeile = ''; V.forEach((v, i) => v.vor.forEach(j => { const a = pos[j], b = pos[i]; const krit = phase === 3 && C[i].gp === 0 && C[j].gp === 0 && C[j].fez === C[i].faz;\n        pfeile += `<line x1=\"${a.x + BW}\" y1=\"${a.y + BH / 2}\" x2=\"${b.x - 4}\" y2=\"${b.y + BH / 2}\" stroke=\"${krit ? 'var(--rot)' : 'currentColor'}\" stroke-width=\"${krit ? 2.5 : 1.3}\" marker-end=\"url(#pf${krit ? 'r' : ''})\"/>`; }));\n      feld.innerHTML = `<svg width=\"800\" height=\"430\" style=\"position:absolute;left:0;top:0;color:var(--tinte2)\"><defs><marker id=\"pf\" markerWidth=\"8\" markerHeight=\"8\" refX=\"7\" refY=\"4\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"currentColor\"/><\/marker><marker id=\"pfr\" markerWidth=\"8\" markerHeight=\"8\" refX=\"7\" refY=\"4\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"var(--rot)\"/><\/marker><\/defs>${pfeile}<\/svg>`;\n      V.forEach((v, i) => { const c = C[i], dran = phase < 3 && i === idx;\n        const w = k => dran && KEYS[phase].includes(k) ? `<div class=\"wert\"><input class=\"np-ein\" data-k=\"${k}\" type=\"number\" placeholder=\"${NAMEN[k]}\" aria-label=\"${NAMEN[k]} Vorgang ${v.nr}\"><\/div>` : `<div class=\"wert${letzter === i && c[k] != null && KEYS[Math.min(phase, 2)].concat(KEYS[Math.max(phase - 1, 0)]).includes(k) ? ' neu' : ''}\">${c[k] == null ? '' : c[k]}<\/div>`;\n        const krit = phase === 3 && c.gp === 0;\n        feld.insertAdjacentHTML('beforeend', `<div class=\"np-k${krit ? ' krit' : ''}${dran ? ' dran' : ''}\" style=\"position:absolute;left:${pos[i].x}px;top:${pos[i].y}px;width:${BW}px\">\n          <div class=\"r\">${w('faz')}<div><\/div>${w('fez')}<\/div>\n          <div class=\"r\"><div>${v.nr}<\/div><div class=\"name\">${v.n}<\/div><\/div>\n          <div class=\"r\"><div>${dauer(i)}${wahlV.wert === i && verz.wert ? '*' : ''}<\/div>${w('gp')}${w('fp')}<\/div>\n          <div class=\"r\">${w('saz')}<div><\/div>${w('sez')}<\/div><\/div>`); });\n      const e = phase >= 1 ? ende() : null;\n      bP.disabled = bN.disabled = bA.disabled = phase === 3;\n      wahlV.el.disabled = verz.el.disabled = phase < 3;\n      if (phase === 3) { info.className = 'info'; info.innerHTML = `Projektdauer: <b>${e} Tage<\/b>${endePlan != null && e !== endePlan ? ` (Plan ${endePlan} Tage – Verschiebung um ${e - endePlan} Tage)` : ''}. Kritischer Pfad (GP = 0): ${V.filter((v, i) => C[i].gp === 0).map(v => v.nr).join(' → ')}.` + (verz.wert ? `<br>Verzögerung von Vorgang ${V[wahlV.wert].nr} um ${verz.wert} Tage: ${e === endePlan ? 'der Gesamtpuffer reicht – das Projektende bleibt.' : 'der Puffer reicht nicht – das Projektende verschiebt sich.'}` : '<br>Jetzt kannst du rechts einen Vorgang verzögern.'); }\n      const inp = feld.querySelector(`input[data-k=\"${phase < 3 ? KEYS[phase][0] : ''}\"]`); if (inp && fokus) inp.focus({preventScroll:true});\n      L.pruefen();\n    }\n    zeichne(); info.innerHTML = 'Start: Vorwärtsrechnung bei Vorgang 1 – trage FAZ und FEZ im gelben Knoten ein.';\n    L.auftraege([\n      {t:'Führe die <b>Vorwärtsrechnung<\/b> durch.', ok:() => phase >= 1},\n      {t:'Führe die <b>Rückwärtsrechnung<\/b> durch.', ok:() => phase >= 2},\n      {t:'Berechne die <b>Puffer<\/b> und finde den kritischen Pfad.', ok:() => phase >= 3},\n      {t:'Verzögere einen Vorgang, <b>ohne<\/b> dass sich das Projektende verschiebt.', ok:() => phase >= 3 && verz.wert > 0 && Math.max(...C.map(c => c.fez)) === endePlan},\n      {t:'Verzögere einen Vorgang so, dass sich das Projektende <b>verschiebt<\/b>.', ok:() => phase >= 3 && Math.max(...C.map(c => c.fez)) > endePlan}\n    ]);\n  }});\n\n/* ======================= Bestellmengen-Labor ======================= */\nlabor({id:'bestellmenge', fach:'BWL, Investition und Finanzierung', titel:'Bestellmengen-Labor: optimale Bestellmenge',\n  intro:'Große Bestellmengen sparen Bestellkosten, verursachen aber hohe Lagerkosten – kleine umgekehrt. Suche mit dem Regler die Menge, bei der die <b>Gesamtkosten<\/b> am niedrigsten sind.',\n  bau(L){\n    const svg = neuesSvg(L.links), info = h('div', {class:'info'}); L.links.append(info);\n    const B = regler(L.rechts, {t:'Jahresbedarf', min:1000, max:20000, step:500, wert:8000, fmt:v => zf(v, 0) + ' Stück'}, zeichne);\n    const KB = regler(L.rechts, {t:'fixe Kosten je Bestellung', min:20, max:300, step:10, wert:100, fmt:v => ze(v)}, zeichne);\n    const P = regler(L.rechts, {t:'Einstandspreis je Stück', min:2, max:100, step:1, wert:20, fmt:v => ze(v)}, zeichne);\n    const Q = regler(L.rechts, {t:'Lagerhaltungskostensatz', min:5, max:30, step:1, wert:10, fmt:v => v + ' %'}, zeichne);\n    const X = regler(L.rechts, {t:'Bestellmenge', min:50, max:3000, step:10, wert:400, fmt:v => zf(v, 0) + ' Stück'}, zeichne);\n    const bk = x => B.wert / x * KB.wert, lk = x => x / 2 * P.wert * Q.wert / 100, opt = () => Math.sqrt(2 * B.wert * KB.wert / (P.wert * Q.wert / 100));\n    function zeichne(){\n      const x = X.wert, xo = opt(), g = t => bk(t) + lk(t), ymax = Math.max(1000, Math.ceil(g(xo) * 2.2 / 500) * 500);\n      plot(svg, {x0:0, x1:3000, y0:0, y1:ymax, xs:500, ys:ymax / 5, fx:v => zf(v, 0), fy:v => zf(v, 0), xt:'Bestellmenge (Stück)', yt:'€ pro Jahr',\n        kurven:[{f:bk, farbe:'var(--blau)'}, {f:lk, farbe:'var(--gold)'}, {f:g, farbe:'var(--rot)', breite:3}], linien:[{x1:x, y1:0, x2:x, y2:ymax, farbe:'var(--tinte)', strich:'3 3'}],\n        punkte:[{x, y:g(x), farbe:'var(--rot)'}], texte:[{x:2950, y:lk(2950) + ymax * 0.03, t:'Lagerkosten', farbe:'var(--gold)', anker:'end'}, {x:2950, y:bk(2950) + ymax * 0.03, t:'Bestellkosten', farbe:'var(--blau)', anker:'end'}, {x:2950, y:Math.min(g(2950), ymax * 0.95) + ymax * 0.03, t:'Gesamtkosten', farbe:'var(--rot)', anker:'end'}]});\n      info.innerHTML = `Bei ${zf(x, 0)} Stück: ${zf(B.wert / x, 1)} Bestellungen; Bestellkosten ${ze(bk(x))}; Lagerkosten ${ze(lk(x))}; <b>Gesamtkosten ${ze(bk(x) + lk(x))}<\/b>.` + (Math.abs(x - xo) / xo <= 0.05 ? `<br><b style=\"color:var(--moos)\">Im Minimum! Andler-Formel: √(2 · ${zf(B.wert, 0)} · ${zf(KB.wert)} ÷ (${zf(P.wert)} · ${Q.wert} %)) ≈ ${zf(xo, 0)} Stück – Bestell- und Lagerkosten sind gleich hoch.<\/b>` : '');\n      L.pruefen();\n    }\n    zeichne();\n    L.auftraege([\n      {t:'Finde mit dem Regler die <b>kostengünstigste Bestellmenge<\/b> (± 5 %).', ok:() => Math.abs(X.wert - opt()) / opt() <= 0.05},\n      {t:'Erhöhe die fixen Bestellkosten auf mindestens 200 € und suche dann mit dem Regler <b>Bestellmenge<\/b> das <b>neue Minimum<\/b> der Gesamtkosten (± 5 %).', ok:() => KB.wert >= 200 && Math.abs(X.wert - opt()) / opt() <= 0.05},\n      {t:'Erhöhe den Lagerhaltungskostensatz auf mindestens 20 % und suche dann mit dem Regler <b>Bestellmenge<\/b> das <b>neue Minimum<\/b> (± 5 %).', ok:() => Q.wert >= 20 && Math.abs(X.wert - opt()) / opt() <= 0.05}\n    ]);\n  }});\n\n/* ======================= Kapitalwert-Labor ======================= */\nlabor({id:'kapitalwert', fach:'BWL, Investition und Finanzierung', titel:'Kapitalwert-Labor: Zinssatz und Investitionsentscheidung',\n  intro:'Der Kapitalwert ist die Summe der abgezinsten Rückflüsse minus Anschaffungsauszahlung. Verändere den Kalkulationszinssatz: Je höher der Zins, desto weniger sind spätere Rückflüsse heute wert. Wo der Kapitalwert 0 ist, liegt der <b>interne Zinsfuß<\/b>.',\n  bau(L){\n    const tab = h('div', {class:'scroll'}), svg = neuesSvg(L.links), info = h('div', {class:'info'}); L.links.prepend(tab); L.links.append(info);\n    const A0 = zahlFeld(L.rechts, 'Anschaffungsauszahlung (€)', 110000, zeichne, {step:1000});\n    const RF = [30000, 35000, 35000, 30000].map((v, i) => zahlFeld(L.rechts, `Rückfluss Jahr ${i + 1} (€)`, v, zeichne, {step:1000}));\n    const I = regler(L.rechts, {t:'Kalkulationszinssatz', min:0, max:20, step:0.5, wert:8, fmt:v => zf(v) + ' %'}, zeichne);\n    const c0 = i => RF.reduce((s, r, t) => s + r.wert / Math.pow(1 + i / 100, t + 1), 0) - A0.wert;\n    const izf = () => { let a = -50, b = 100; if (c0(a) * c0(b) > 0) return null; for (let k = 0; k < 80; k++){ const m = (a + b) / 2; if (c0(a) * c0(m) <= 0) b = m; else a = m; } return (a + b) / 2; };\n    function zeichne(){\n      const i = I.wert, q = 1 + i / 100;\n      tab.innerHTML = '<table class=\"lab\"><tr><th>Jahr<\/th><th>Rückfluss<\/th><th>Abzinsungsfaktor<\/th><th>Barwert<\/th><\/tr>' + RF.map((r, t) => `<tr><td>${t + 1}<\/td><td>${zeG(r.wert)}<\/td><td>1 ÷ ${zf(q, 3)}<sup>${t + 1}<\/sup> = ${zf(1 / Math.pow(q, t + 1), 4)}<\/td><td>${zeG(r.wert / Math.pow(q, t + 1))}<\/td><\/tr>`).join('') +\n        `<tr class=\"summe\"><td>Summe<\/td><td><\/td><td><\/td><td>${zeG(c0(i) + A0.wert)}<\/td><\/tr><tr><td>− Anschaffung<\/td><td><\/td><td><\/td><td>${zeG(A0.wert)}<\/td><\/tr><tr class=\"summe\"><td>Kapitalwert<\/td><td><\/td><td><\/td><td style=\"color:${c0(i) >= 0 ? 'var(--moos)' : 'var(--rot)'}\">${zeG(c0(i))}<\/td><\/tr><\/table>`;\n      const z = izf(), ys = [0, 5, 10, 15, 20, 25].map(c0), lo = Math.min(...ys, 0), hi = Math.max(...ys, 0), st = Math.max(5000, Math.ceil((hi - lo) / 6 / 5000) * 5000);\n      plot(svg, {x0:0, x1:25, y0:Math.floor(lo / st) * st, y1:Math.ceil(hi / st) * st, xs:5, ys:st, fx:v => zf(v, 0) + ' %', fy:v => zf(v / 1000, 0) + ' T', xt:'Zinssatz', yt:'Kapitalwert (€)',\n        kurven:[{f:c0}], punkte:[{x:i, y:c0(i), farbe:'var(--blau)', t:zf(i) + ' %'}].concat(z != null && z >= 0 && z <= 25 ? [{x:z, y:0, farbe:'var(--moos)', t:'interner Zinsfuß ' + zf(z) + ' %'}] : [])});\n      info.className = 'info ' + (c0(i) >= 0 ? 'gut' : 'schlecht');\n      info.innerHTML = c0(i) >= 0 ? `Kapitalwert ≥ 0: Die Investition lohnt sich bei ${zf(i)} % (Verzinsung mindestens erreicht).` : `Kapitalwert < 0: Bei ${zf(i)} % lohnt sich die Investition nicht.`;\n      L.pruefen();\n    }\n    zeichne();\n    L.auftraege([\n      {t:'Lies den Kapitalwert bei <b>6 %<\/b> ab – lohnt sich die Investition?', ok:() => I.wert === 6},\n      {t:'Finde den Zinssatz, bei dem der Kapitalwert ungefähr <b>0<\/b> ist (|C₀| < 1.000 €).', ok:() => Math.abs(c0(I.wert)) < 1000},\n      {t:'Stelle 10 % ein und erhöhe einen Rückfluss so, dass sich die Investition <b>gerade lohnt<\/b> (C₀ ≥ 0).', ok:() => I.wert === 10 && c0(10) >= 0}\n    ]);\n  }});\n\n/* ======================= Tilgungsplan-Werkstatt ======================= */\nlabor({id:'tilgung', fach:'BWL, Investition und Finanzierung', titel:'Tilgungsplan-Werkstatt: Darlehensarten vergleichen',\n  intro:'Baue den Tilgungsplan Jahr für Jahr auf. Vergleiche Ratentilgung, Annuitätendarlehen und Fälligkeitsdarlehen: Wie verteilen sich Zinsen und Tilgung, und welche Art kostet insgesamt die wenigsten Zinsen?',\n  bau(L){\n    const tab = h('div', {class:'scroll'}), svg = neuesSvg(L.links), info = h('div', {class:'info'}); L.links.append(tab, svg, info);\n    const ART = ['Ratentilgung', 'Annuitätendarlehen', 'Fälligkeitsdarlehen'];\n    const art = auswahl(L.rechts, 'Darlehensart', ART, neu);\n    const K = zahlFeld(L.rechts, 'Darlehen (€)', 50000, neu, {step:1000}), Z = zahlFeld(L.rechts, 'Zinssatz (%)', 5, neu, {step:0.5}), N = zahlFeld(L.rechts, 'Laufzeit (Jahre)', 5, neu, {step:1, min:1, max:10});\n    L.rechts.append(h('div', {class:'knoepfe'}, h('button', {class:'knopf primaer', onclick:jahr}, 'Nächstes Jahr'), h('button', {class:'knopf', onclick:() => { while (zeilen.length < N.wert) jahr(true); zeichne(); }}, 'Alle Jahre'), h('button', {class:'knopf', onclick:neu}, 'Neu starten')));\n    const fertig = {}; let zeilen = [];\n    function neu(){ zeilen = []; zeichne(); }\n    function jahr(still){\n      const n = Math.max(1, Math.round(N.wert)), k = K.wert, z = Z.wert / 100; if (zeilen.length >= n) return;\n      const rs = zeilen.length ? zeilen[zeilen.length - 1].ende : k, zi = rs * z; let t;\n      if (art.wert === 0) t = k / n; else if (art.wert === 1){ const ann = k * z * Math.pow(1 + z, n) / (Math.pow(1 + z, n) - 1); t = ann - zi; } else t = zeilen.length === n - 1 ? k : 0;\n      zeilen.push({j:zeilen.length + 1, anf:rs, zi, t, rate:zi + t, ende:Math.max(0, rs - t)});\n      if (zeilen.length === n) fertig[art.wert] = zeilen.reduce((s, r) => s + r.zi, 0);\n      if (!still) zeichne();\n    }\n    function zeichne(){\n      tab.innerHTML = '<table class=\"lab\"><tr><th>Jahr<\/th><th>Restschuld Jahresanfang<\/th><th>Zinsen<\/th><th>Tilgung<\/th><th>Rate (Zinsen + Tilgung)<\/th><th>Restschuld Jahresende<\/th><\/tr>' +\n        zeilen.map((r, i) => `<tr${i === zeilen.length - 1 ? ' class=\"neu\"' : ''}><td>${r.j}<\/td><td>${ze(r.anf)}<\/td><td>${ze(r.zi)}<\/td><td>${ze(r.t)}<\/td><td>${ze(r.rate)}<\/td><td>${ze(r.ende)}<\/td><\/tr>`).join('') +\n        (zeilen.length ? `<tr class=\"summe\"><td>Summe<\/td><td><\/td><td>${ze(zeilen.reduce((s, r) => s + r.zi, 0))}<\/td><td>${ze(zeilen.reduce((s, r) => s + r.t, 0))}<\/td><td>${ze(zeilen.reduce((s, r) => s + r.rate, 0))}<\/td><td><\/td><\/tr>` : '') + '<\/table>';\n      const n = Math.max(1, Math.round(N.wert)), ymax = Math.max(1000, ...zeilen.map(r => r.rate)) * 1.15, fl = [];\n      zeilen.forEach(r => { fl.push({pts:[[r.j - 0.35, 0], [r.j + 0.35, 0], [r.j + 0.35, r.t], [r.j - 0.35, r.t]], farbe:'var(--blau)', deckung:.7}, {pts:[[r.j - 0.35, r.t], [r.j + 0.35, r.t], [r.j + 0.35, r.t + r.zi], [r.j - 0.35, r.t + r.zi]], farbe:'var(--rot)', deckung:.7}); });\n      plot(svg, {x0:0.3, x1:n + 0.7, y0:0, y1:ymax, xs:1, ys:Math.max(1000, Math.ceil(ymax / 5 / 1000) * 1000), fx:v => zf(v, 0), fy:v => zf(v / 1000, 0) + ' T', xt:'Jahr', flaechen:fl,\n        texte:[{x:0.4, y:ymax * 0.93, t:'■ Tilgung', farbe:'var(--blau)'}, {x:0.4 + n * 0.25, y:ymax * 0.93, t:'■ Zinsen', farbe:'var(--rot)'}]});\n      info.innerHTML = Object.keys(fertig).length ? 'Zinsen insgesamt: ' + Object.entries(fertig).map(([a, v]) => `${ART[a]} <b>${ze(v)}<\/b>`).join('; ') + (Object.keys(fertig).length === 3 ? '<br>Je schneller getilgt wird, desto weniger Zinsen fallen an – aber desto höher ist die Belastung am Anfang.' : '') : 'Baue den Plan mit „Nächstes Jahr“ auf.';\n      L.pruefen();\n    }\n    neu();\n    const wahlBox = h('div'); L.rechts.append(h('div', {class:'augenbraue', style:'margin-top:.8rem'}, 'Frage'), h('p', {}, 'Welche Darlehensart verursacht die geringsten Gesamtzinsen?'), wahlBox);\n    let antwort = null; ART.forEach((a, i) => wahlBox.append(h('button', {class:'knopf', style:'margin:.15rem', onclick:e => { antwort = i; wahlBox.querySelectorAll('button').forEach(b => b.classList.remove('primaer')); e.target.classList.add('primaer'); info.innerHTML += i === 0 ? '<br><b style=\"color:var(--moos)\">Richtig: Bei der Ratentilgung sinkt die Restschuld am schnellsten.<\/b>' : '<br><b style=\"color:var(--rot)\">Noch nicht – vergleiche die Zinssummen.<\/b>'; L.pruefen(); }}, a)));\n    L.auftraege([\n      {t:'Erstelle den vollständigen Plan für die <b>Ratentilgung<\/b>.', ok:() => fertig[0] != null},\n      {t:'Erstelle den vollständigen Plan für das <b>Annuitätendarlehen<\/b>.', ok:() => fertig[1] != null},\n      {t:'Erstelle den vollständigen Plan für das <b>Fälligkeitsdarlehen<\/b>.', ok:() => fertig[2] != null},\n      {t:'Beantworte die Frage: geringste Gesamtzinsen.', ok:() => antwort === 0}\n    ]);\n  }});\n/* ---------- Labor: Volkswirtschaft ---------- */\nlabor({id:'markt', fach:'Volkswirtschaft', titel:'Markt-Labor: Angebot, Nachfrage und Staatseingriffe',\n  intro:'Im Schnittpunkt von Angebots- und Nachfragekurve liegt das <b>Marktgleichgewicht<\/b>. Verschiebe die Kurven (z. B. höheres Einkommen, Missernte) oder setze einen staatlichen Höchst- bzw. Mindestpreis und beobachte die Folgen.',\n  bau(L){\n    const svg = neuesSvg(L.links), info = h('div', {class:'info'}); L.links.append(info);\n    const rl = v => v > 0 ? 'nach rechts, +' + zf(v, 0) + ' Stück' : v < 0 ? 'nach links, −' + zf(-v, 0) + ' Stück' : 'unverändert';\n    const SN = regler(L.rechts, {t:'Nachfrage verschieben', min:-600, max:600, step:50, wert:0, fmt:rl}, zeichne);\n    const SA = regler(L.rechts, {t:'Angebot verschieben', min:-600, max:600, step:50, wert:0, fmt:rl}, zeichne);\n    const EG = auswahl(L.rechts, 'Staatlicher Eingriff', ['kein Eingriff', 'Höchstpreis', 'Mindestpreis'], zeichne);\n    const PS = regler(L.rechts, {t:'staatlich festgesetzter Preis', min:2, max:20, step:0.5, wert:8, fmt:v => ze(v)}, zeichne);\n    const nach = (x, s) => 20 - 0.01 * (x - s), ang = (x, s) => 4 + 0.006 * (x - s);\n    let Z = {};\n    function zeichne(){\n      const sn = SN.wert, sa = SA.wert, xg = (16 + 0.01 * sn + 0.006 * sa) / 0.016, pg = nach(xg, sn), e = EG.wert, ps = PS.wert;\n      const xN = p => (20 - p) / 0.01 + sn, xA = p => (p - 4) / 0.006 + sa;\n      const lin = [], pk = [{x:xg, y:pg, farbe:'var(--tinte)', t:'Gleichgewicht'}]; let txt = `Gleichgewicht: Preis <b>${ze(pg)}<\/b>, Menge <b>${zf(xg, 0)} Stück<\/b>.`;\n      Z = {pg, xg, ue:0, wirksam:false};\n      if (e){ lin.push({x1:0, y1:ps, x2:2400, y2:ps, farbe:e === 1 ? 'var(--blau)' : 'var(--gold)', breite:2, strich:'6 4'});\n        const wirk = e === 1 ? ps < pg : ps > pg; Z.wirksam = wirk;\n        if (wirk){ const a = Math.max(0, xA(ps)), n = Math.max(0, xN(ps)); Z.ue = Math.abs(n - a); lin.push({x1:Math.min(a, n), y1:ps, x2:Math.max(a, n), y2:ps, farbe:'var(--rot)', breite:5});\n          txt += `<br>${e === 1 ? 'Höchstpreis' : 'Mindestpreis'} ${ze(ps)} ist <b>wirksam<\/b>: Angebot ${zf(a, 0)} Stück, Nachfrage ${zf(n, 0)} Stück → <b style=\"color:var(--rot)\">${e === 1 ? 'Nachfrageüberhang' : 'Angebotsüberhang'} ${zf(Z.ue, 0)} Stück<\/b>.`; }\n        else txt += `<br>${e === 1 ? 'Höchstpreis' : 'Mindestpreis'} ${ze(ps)} liegt ${e === 1 ? 'über' : 'unter'} dem Gleichgewichtspreis – er ist <b>wirkungslos<\/b>.`; }\n      plot(svg, {x0:0, x1:2400, y0:0, y1:24, xs:400, ys:2, fx:v => zf(v, 0), fy:v => zf(v, 0), xt:'Menge (Stück)', yt:'Preis (€)',\n        kurven:[{f:x => nach(x, 0), farbe:'var(--moos)', breite:1.2, strich:'4 4'}, {f:x => ang(x, 0), farbe:'var(--blau)', breite:1.2, strich:'4 4'}, {f:x => nach(x, sn), farbe:'var(--moos)'}, {f:x => ang(x, sa), farbe:'var(--blau)'}],\n        linien:lin, punkte:pk, texte:[{x:2350, y:Math.max(1, nach(2350, sn)) + 0.6, t:'Nachfrage', farbe:'var(--moos)', anker:'end'}, {x:2350, y:Math.min(23, ang(2350, sa)) - 0.8, t:'Angebot', farbe:'var(--blau)', anker:'end'}]});\n      info.innerHTML = txt + (sn || sa ? `<br>Gegenüber dem Ausgangsgleichgewicht (10,00 €, 1.000 Stück): Preis ${pg > 10.004 ? 'steigt' : pg < 9.996 ? 'sinkt' : 'bleibt'}, Menge ${xg > 1000.5 ? 'steigt' : xg < 999.5 ? 'sinkt' : 'bleibt'}.` : '');\n      L.pruefen();\n    }\n    zeichne();\n    L.auftraege([\n      {t:'Die Einkommen steigen: Verschiebe die <b>Nachfrage nach rechts<\/b> und beobachte Preis und Menge.', ok:() => SN.wert > 0 && SA.wert === 0},\n      {t:'Missernte: Das <b>Angebot geht zurück<\/b> (Angebotskurve nach links).', ok:() => SA.wert < 0 && SN.wert === 0},\n      {t:'Setze einen <b>wirksamen Höchstpreis<\/b> mit einem Nachfrageüberhang von mindestens 500 Stück.', ok:() => EG.wert === 1 && Z.wirksam && Z.ue >= 500},\n      {t:'Setze einen <b>Mindestpreis, der wirkungslos<\/b> ist.', ok:() => EG.wert === 2 && !Z.wirksam}\n    ]);\n  }});\n\nif (window.LABOR_SOLO) startSolo(window.LABOR_SOLO); else start();\n<\/script>\n<\/body><\/html>\n";/*LABOR-QUELLE*/
